import { useState, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  Upload,
  Camera,
  ArrowRight,
  ArrowLeft,
  Check,
  Sparkles,
  RefreshCw,
  Image as ImageIcon,
} from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';
import { fileToDataUrl, loadImage, resizeImage } from '@/utils/image';
import { analyzeSkinTone } from '@/utils/skin';
import { detectLipRegion } from '@/utils/lip';
import type { SkinAnalysis, LipRegion } from '@/types';

export default function SelfiePage() {
  const navigate = useNavigate();
  const {
    selfieImage,
    setSelfieImage,
    setSkinAnalysis,
    setLipRegion,
    setCurrentStep,
  } = useAppStore();

  const [isDragging, setIsDragging] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<SkinAnalysis | null>(null);
  const [lipRegion, setLipRegionState] = useState<LipRegion | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const handleFile = useCallback(
    async (file: File) => {
      if (!file.type.startsWith('image/')) return;

      setIsAnalyzing(true);
      setUploadProgress(30);

      try {
        const dataUrl = await fileToDataUrl(file);
        setUploadProgress(50);

        const img = await loadImage(dataUrl);
        const resized = resizeImage(img, 800, 800);
        setUploadProgress(70);

        setSelfieImage(resized);
        setUploadProgress(85);

        const [skinResult, lipResult] = await Promise.all([
          analyzeSkinTone(resized),
          detectLipRegion(resized),
        ]);

        setAnalysisResult(skinResult);
        setLipRegionState(lipResult);
        setSkinAnalysis(skinResult);
        setLipRegion(lipResult);
        setUploadProgress(100);

        setTimeout(() => {
          setIsAnalyzing(false);
        }, 500);
      } catch (error) {
        console.error('分析失败:', error);
        setIsAnalyzing(false);
      }
    },
    [setSelfieImage, setSkinAnalysis, setLipRegion]
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(false);
      const file = e.dataTransfer.files[0];
      if (file) handleFile(file);
    },
    [handleFile]
  );

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) handleFile(file);
  };

  const handleReanalyze = async () => {
    if (!selfieImage) return;
    setIsAnalyzing(true);
    try {
      const [skinResult, lipResult] = await Promise.all([
        analyzeSkinTone(selfieImage),
        detectLipRegion(selfieImage),
      ]);
      setAnalysisResult(skinResult);
      setLipRegionState(lipResult);
      setSkinAnalysis(skinResult);
      setLipRegion(lipResult);
    } catch (error) {
      console.error('重新分析失败:', error);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleNext = () => {
    setCurrentStep(2);
    navigate('/products');
  };

  const handleBack = () => {
    setCurrentStep(0);
    navigate('/');
  };

  const depthLabels: Record<string, string> = {
    fair: '白皙',
    light: '偏白',
    medium: '自然',
    tan: '小麦',
    deep: '健康古铜',
  };

  const toneLabels: Record<string, string> = {
    warm: '暖调',
    cool: '冷调',
    neutral: '中性调',
  };

  return (
    <div className="container py-12">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-5xl mx-auto"
      >
        <div className="text-center mb-10">
          <h1 className="font-display text-3xl md:text-4xl font-bold text-wine mb-3">
            上传你的自拍
          </h1>
          <p className="text-wine/60">
            AI 将自动识别肤色特征和嘴唇区域，为你定制专属试色
          </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-8">
          <div className="space-y-6">
            <div
              className={`card-luxury p-8 border-2 border-dashed transition-all cursor-pointer ${
                isDragging
                  ? 'border-gold bg-gold/5'
                  : 'border-blush hover:border-rose-gold-light'
              }`}
              onDragOver={(e) => {
                e.preventDefault();
                setIsDragging(true);
              }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
            >
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                onChange={handleInputChange}
                className="hidden"
              />

              <AnimatePresence mode="wait">
                {!selfieImage ? (
                  <motion.div
                    key="upload"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="text-center py-8"
                  >
                    <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-blush/50 flex items-center justify-center">
                      <Camera className="w-10 h-10 text-rose-gold" />
                    </div>
                    <h3 className="font-semibold text-lg text-wine mb-2">
                      上传正面自拍
                    </h3>
                    <p className="text-wine/60 text-sm mb-4">
                      拖拽图片到此处，或点击选择文件
                    </p>
                    <div className="flex items-center justify-center gap-2 text-sm text-wine/50">
                      <ImageIcon className="w-4 h-4" />
                      <span>支持 JPG、PNG 格式</span>
                    </div>
                  </motion.div>
                ) : (
                  <motion.div
                    key="preview"
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0 }}
                    className="relative"
                  >
                    <div className="relative rounded-xl overflow-hidden aspect-[3/4] bg-blush/30">
                      <img
                        src={selfieImage}
                        alt="自拍预览"
                        className="w-full h-full object-cover"
                      />
                      <canvas
                        ref={canvasRef}
                        className="absolute inset-0 w-full h-full pointer-events-none"
                      />
                      {isAnalyzing && (
                        <div className="absolute inset-0 bg-wine/30 flex items-center justify-center">
                          <div className="text-center text-white">
                            <motion.div
                              animate={{ rotate: 360 }}
                              transition={{
                                duration: 1.5,
                                repeat: Infinity,
                                ease: 'linear',
                              }}
                              className="w-12 h-12 mx-auto mb-3 rounded-full border-4 border-white/30 border-t-white"
                            />
                            <p className="font-medium">AI 分析中...</p>
                            <p className="text-sm opacity-80">
                              {uploadProgress}%
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                    <div className="flex gap-2 mt-4">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          fileInputRef.current?.click();
                        }}
                        className="flex-1 btn-outline-gold py-2 text-sm flex items-center justify-center gap-2"
                      >
                        <Upload className="w-4 h-4" />
                        重新上传
                      </button>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleReanalyze();
                        }}
                        disabled={isAnalyzing}
                        className="flex-1 btn-outline-gold py-2 text-sm flex items-center justify-center gap-2 disabled:opacity-50"
                      >
                        <RefreshCw
                          className={`w-4 h-4 ${isAnalyzing ? 'animate-spin' : ''}`}
                        />
                        重新分析
                      </button>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            <div className="card-luxury p-6">
              <h3 className="font-semibold text-wine mb-4 flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-gold" />
                拍照小贴士
              </h3>
              <ul className="space-y-2 text-sm text-wine/70">
                <li className="flex items-start gap-2">
                  <Check className="w-4 h-4 text-rose-gold flex-shrink-0 mt-0.5" />
                  <span>光线充足的环境下拍摄，避免阴影</span>
                </li>
                <li className="flex items-start gap-2">
                  <Check className="w-4 h-4 text-rose-gold flex-shrink-0 mt-0.5" />
                  <span>正面朝向镜头，露出完整的嘴唇</span>
                </li>
                <li className="flex items-start gap-2">
                  <Check className="w-4 h-4 text-rose-gold flex-shrink-0 mt-0.5" />
                  <span>素颜或淡妆，让肤色分析更准确</span>
                </li>
                <li className="flex items-start gap-2">
                  <Check className="w-4 h-4 text-rose-gold flex-shrink-0 mt-0.5" />
                  <span>照片清晰，无模糊和过度曝光</span>
                </li>
              </ul>
            </div>
          </div>

          <div className="space-y-6">
            <AnimatePresence mode="wait">
              {analysisResult ? (
                <motion.div
                  key="result"
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -20 }}
                  className="space-y-6"
                >
                  <div className="card-luxury p-6">
                    <h3 className="font-semibold text-wine mb-4 flex items-center gap-2">
                      <div className="w-8 h-8 rounded-full bg-rose-gold-gradient flex items-center justify-center">
                        <Sparkles className="w-4 h-4 text-white" />
                      </div>
                      肤色分析结果
                    </h3>

                    <div className="flex items-center gap-4 mb-6">
                      <div
                        className="w-20 h-20 rounded-full shadow-lg border-4 border-white"
                        style={{ backgroundColor: analysisResult.dominantColor }}
                      />
                      <div>
                        <p className="font-semibold text-xl text-wine">
                          {depthLabels[analysisResult.depth]}肤色
                        </p>
                        <p className="text-rose-gold font-medium">
                          {toneLabels[analysisResult.tone]}
                        </p>
                        <p className="text-sm text-wine/50 mt-1">
                          {analysisResult.undertone}
                        </p>
                      </div>
                    </div>

                    <div className="space-y-4">
                      <div>
                        <div className="flex justify-between text-sm mb-1.5">
                          <span className="text-wine/70">肤色深浅度</span>
                          <span className="font-medium text-wine">
                            {Math.round(analysisResult.brightness)}%
                          </span>
                        </div>
                        <div className="h-2 bg-blush rounded-full overflow-hidden">
                          <motion.div
                            initial={{ width: 0 }}
                            animate={{ width: `${analysisResult.brightness}%` }}
                            transition={{ duration: 1, delay: 0.2 }}
                            className="h-full bg-rose-gold-gradient rounded-full"
                          />
                        </div>
                      </div>

                      <div>
                        <div className="flex justify-between text-sm mb-1.5">
                          <span className="text-wine/70">冷暖调倾向</span>
                          <span className="font-medium text-wine">
                            {analysisResult.tone === 'warm'
                              ? '偏暖'
                              : analysisResult.tone === 'cool'
                              ? '偏冷'
                              : '中性'}
                          </span>
                        </div>
                        <div className="h-2 bg-blush rounded-full overflow-hidden flex">
                          <div className="flex-1 bg-gradient-to-r from-orange-300 to-pink-300" />
                          <div className="flex-1 bg-gradient-to-r from-pink-300 to-blue-300" />
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="card-luxury p-6">
                    <h3 className="font-semibold text-wine mb-4">肤色特征标签</h3>
                    <div className="flex flex-wrap gap-2">
                      {analysisResult.labels.map((label, index) => (
                        <motion.span
                          key={label}
                          initial={{ opacity: 0, scale: 0.8 }}
                          animate={{ opacity: 1, scale: 1 }}
                          transition={{ delay: index * 0.1 }}
                          className="px-3 py-1.5 rounded-full bg-gradient-to-r from-rose-gold-light/20 to-gold/20 text-wine text-sm border border-rose-gold-light/30"
                        >
                          {label}
                        </motion.span>
                      ))}
                    </div>
                  </div>

                  {lipRegion && (
                    <div className="card-luxury p-6">
                      <h3 className="font-semibold text-wine mb-3">
                        嘴唇区域识别
                      </h3>
                      <div className="flex items-center justify-between">
                        <span className="text-wine/70 text-sm">识别置信度</span>
                        <span className="font-medium text-rose-gold">
                          {Math.round(lipRegion.confidence * 100)}%
                        </span>
                      </div>
                      <div className="mt-2 h-2 bg-blush rounded-full overflow-hidden">
                        <motion.div
                          initial={{ width: 0 }}
                          animate={{ width: `${lipRegion.confidence * 100}%` }}
                          transition={{ duration: 1, delay: 0.5 }}
                          className="h-full bg-gold-gradient rounded-full"
                        />
                      </div>
                    </div>
                  )}
                </motion.div>
              ) : (
                <motion.div
                  key="placeholder"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="card-luxury p-8 text-center"
                >
                  <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-blush/50 flex items-center justify-center">
                    <Sparkles className="w-8 h-8 text-rose-gold/50" />
                  </div>
                  <h3 className="font-semibold text-wine mb-2">等待分析</h3>
                  <p className="text-wine/50 text-sm">
                    上传自拍后，AI 将自动分析你的肤色特征
                  </p>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>

        <div className="flex justify-between mt-10">
          <button
            onClick={handleBack}
            className="btn-outline-gold flex items-center gap-2"
          >
            <ArrowLeft className="w-5 h-5" />
            返回首页
          </button>
          <button
            onClick={handleNext}
            disabled={!analysisResult || isAnalyzing}
            className="btn-rose-gold flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            下一步：选择口红
            <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      </motion.div>
    </div>
  );
}
