import type { SkinAnalysis, Product, Recommendation, ExtractedColor } from '@/types';
import { hexToRgb, rgbToHsl, getWarmCoolScore } from './color';

export const generateRecommendations = (
  products: Product[],
  skinAnalysis: SkinAnalysis,
  likedProductIds: string[]
): Recommendation[] => {
  const recommendations: Recommendation[] = products.map((product) => {
    const skinMatch = calculateSkinMatch(product.extractedColor, skinAnalysis);
    const preferenceMatch = calculatePreferenceMatch(
      product.extractedColor,
      products,
      likedProductIds
    );

    const skinWeight = skinAnalysis ? 0.6 : 0.3;
    const prefWeight = likedProductIds.length > 0 ? 0.4 : 0.1;
    const totalWeight = skinWeight + prefWeight;

    const matchScore = Math.round(
      ((skinMatch * skinWeight + preferenceMatch * prefWeight) / totalWeight) * 100
    );

    const reasons = generateReasons(
      product,
      skinAnalysis,
      skinMatch,
      preferenceMatch,
      likedProductIds.length > 0
    );

    return {
      productId: product.id,
      matchScore,
      skinMatch: Math.round(skinMatch * 100),
      preferenceMatch: Math.round(preferenceMatch * 100),
      reasons,
      rank: 0,
    };
  });

  recommendations.sort((a, b) => b.matchScore - a.matchScore);
  recommendations.forEach((rec, idx) => {
    rec.rank = idx + 1;
  });

  return recommendations;
};

const calculateSkinMatch = (
  color: ExtractedColor,
  skinAnalysis: SkinAnalysis
): number => {
  let score = 0.5;

  const warmCoolScore = getWarmCoolScore(color.hsl.h, color.hsl.s);

  if (skinAnalysis.tone === 'warm') {
    if (warmCoolScore > 0) {
      score += 0.25;
    } else if (warmCoolScore < -0.3) {
      score -= 0.15;
    }
  } else if (skinAnalysis.tone === 'cool') {
    if (warmCoolScore < 0) {
      score += 0.25;
    } else if (warmCoolScore > 0.3) {
      score -= 0.15;
    }
  } else {
    score += 0.15;
  }

  const depthScore = calculateDepthMatch(color.hsl.l, skinAnalysis.depth);
  score += depthScore * 0.2;

  const rednessMatch = calculateRednessMatch(color, skinAnalysis);
  score += rednessMatch * 0.15;

  return Math.max(0, Math.min(1, score));
};

const calculateDepthMatch = (
  colorLightness: number,
  skinDepth: string
): number => {
  const depthLightness: Record<string, number> = {
    fair: 75,
    light: 60,
    medium: 45,
    tan: 35,
    deep: 25,
  };

  const skinLightness = depthLightness[skinDepth] || 50;

  const contrast = Math.abs(colorLightness - skinLightness);

  if (skinDepth === 'fair' || skinDepth === 'light') {
    if (contrast > 20 && contrast < 50) return 1;
    if (contrast > 10) return 0.7;
    return 0.4;
  } else if (skinDepth === 'medium' || skinDepth === 'tan') {
    if (contrast > 15 && contrast < 45) return 1;
    if (contrast > 10) return 0.7;
    return 0.5;
  } else {
    if (colorLightness < 50) return 0.9;
    if (colorLightness < 70) return 0.7;
    return 0.5;
  }
};

const calculateRednessMatch = (
  color: ExtractedColor,
  skinAnalysis: SkinAnalysis
): number => {
  if (skinAnalysis.redness > 0.1) {
    if (color.hsl.h > 20 && color.hsl.h < 60) {
      return 0.3;
    }
    if (color.hsl.s < 50) {
      return 0.2;
    }
    return -0.1;
  }
  return 0;
};

const calculatePreferenceMatch = (
  color: ExtractedColor,
  products: Product[],
  likedProductIds: string[]
): number => {
  if (likedProductIds.length === 0) return 0.5;

  const likedProducts = products.filter((p) => likedProductIds.includes(p.id));
  if (likedProducts.length === 0) return 0.5;

  const avgHue =
    likedProducts.reduce((sum, p) => sum + p.extractedColor.hsl.h, 0) /
    likedProducts.length;
  const avgSat =
    likedProducts.reduce((sum, p) => sum + p.extractedColor.hsl.s, 0) /
    likedProducts.length;
  const avgLight =
    likedProducts.reduce((sum, p) => sum + p.extractedColor.hsl.l, 0) /
    likedProducts.length;

  let hueDiff = Math.abs(color.hsl.h - avgHue);
  if (hueDiff > 180) hueDiff = 360 - hueDiff;
  const hueScore = Math.max(0, 1 - hueDiff / 60);

  const satDiff = Math.abs(color.hsl.s - avgSat);
  const satScore = Math.max(0, 1 - satDiff / 40);

  const lightDiff = Math.abs(color.hsl.l - avgLight);
  const lightScore = Math.max(0, 1 - lightDiff / 30);

  const categoryMatch = likedProducts.some(
    (p) => p.extractedColor.category === color.category
  );
  const categoryScore = categoryMatch ? 1 : 0.5;

  return hueScore * 0.4 + satScore * 0.2 + lightScore * 0.2 + categoryScore * 0.2;
};

const generateReasons = (
  product: Product,
  skinAnalysis: SkinAnalysis,
  skinMatch: number,
  preferenceMatch: number,
  hasPreference: boolean
): string[] => {
  const reasons: string[] = [];
  const color = product.extractedColor;

  if (skinMatch >= 0.7) {
    if (skinAnalysis.tone === 'warm') {
      reasons.push(
        `根据你的暖调肤色，这支${color.name}能提亮气色，显白效果好`
      );
    } else if (skinAnalysis.tone === 'cool') {
      reasons.push(
        `你的冷调肤色与这支${color.name}完美契合，显高级感`
      );
    } else {
      reasons.push(
        `你的中性肤色可以轻松驾驭这支${color.name}，不挑皮`
      );
    }
  } else if (skinMatch >= 0.5) {
    reasons.push(`这支${color.name}与你的肤色搭配度中等，可以尝试`);
  }

  const depthLabels: Record<string, string> = {
    fair: '白皙',
    light: '偏白',
    medium: '自然',
    tan: '小麦',
    deep: '健康',
  };

  if (color.hsl.l > 60 && (skinAnalysis.depth === 'fair' || skinAnalysis.depth === 'light')) {
    reasons.push(`浅色系的${color.name}适合你的${depthLabels[skinAnalysis.depth]}肤色，打造清新妆容`);
  }

  if (color.hsl.l < 40 && (skinAnalysis.depth === 'tan' || skinAnalysis.depth === 'deep')) {
    reasons.push(`浓郁的${color.name}能衬托你的${depthLabels[skinAnalysis.depth]}肤色，气场十足`);
  }

  if (hasPreference && preferenceMatch >= 0.7) {
    reasons.push(`与你喜欢的风格相近，属于${color.category}，很符合你的审美偏好`);
  }

  if (color.category === '正红色系') {
    reasons.push('经典正红色，百搭不出错，任何场合都能hold住');
  } else if (color.category === '裸粉色系' || color.category === '裸色系') {
    reasons.push('日常通勤首选，自然提气色，伪素颜必备');
  } else if (color.category === '橘调色系') {
    reasons.push('橘调显白又减龄，黄皮友好，夏日必备');
  } else if (color.category === '玫红色系') {
    reasons.push('玫红显白提气质，冷白皮涂了超好看');
  }

  return reasons.slice(0, 3);
};

export const analyzeUserPreferences = (
  products: Product[],
  likedProductIds: string[]
): {
  preferredCategories: string[];
  preferredTones: string[];
  styleTags: string[];
} => {
  const likedProducts = products.filter((p) => likedProductIds.includes(p.id));
  if (likedProducts.length === 0) {
    return {
      preferredCategories: [],
      preferredTones: [],
      styleTags: ['待发掘'],
    };
  }

  const categoryCount: Record<string, number> = {};
  likedProducts.forEach((p) => {
    const cat = p.extractedColor.category;
    categoryCount[cat] = (categoryCount[cat] || 0) + 1;
  });

  const preferredCategories = Object.entries(categoryCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([cat]) => cat);

  const warmCount = likedProducts.filter((p) => {
    const h = p.extractedColor.hsl.h;
    return h < 50 || h > 330;
  }).length;

  const coolCount = likedProducts.filter((p) => {
    const h = p.extractedColor.hsl.h;
    return h >= 270 && h <= 330;
  }).length;

  const preferredTones: string[] = [];
  if (warmCount > coolCount) preferredTones.push('暖调');
  else if (coolCount > warmCount) preferredTones.push('冷调');
  else preferredTones.push('中性调');

  const avgLight =
    likedProducts.reduce((sum, p) => sum + p.extractedColor.hsl.l, 0) /
    likedProducts.length;

  const styleTags: string[] = [];

  if (avgLight > 65) {
    styleTags.push('清新自然', '日常通勤');
  } else if (avgLight > 45) {
    styleTags.push('气质优雅', '百搭经典');
  } else {
    styleTags.push('气场强大', '浓郁复古');
  }

  if (preferredCategories.includes('正红色系')) {
    styleTags.push('经典不败');
  }
  if (preferredCategories.includes('裸粉色系')) {
    styleTags.push('温柔知性');
  }
  if (preferredCategories.includes('橘调色系')) {
    styleTags.push('活力元气');
  }
  if (preferredCategories.includes('玫红色系')) {
    styleTags.push('时尚前卫');
  }

  return {
    preferredCategories,
    preferredTones,
    styleTags: [...new Set(styleTags)].slice(0, 5),
  };
};
