import { create } from 'zustand';
import type {
  UserSession,
  Product,
  TryOnResult,
  SkinAnalysis,
  LipRegion,
  Recommendation,
} from '@/types';
import { mockProducts } from '@/data/products';

const FAVORITES_STORAGE_KEY = 'ai-mirror-favorites';

const loadFavoritesFromStorage = (): string[] => {
  try {
    const stored = localStorage.getItem(FAVORITES_STORAGE_KEY);
    if (stored) {
      return JSON.parse(stored);
    }
  } catch (e) {
    console.error('加载收藏失败:', e);
  }
  return [];
};

const saveFavoritesToStorage = (favorites: string[]) => {
  try {
    localStorage.setItem(FAVORITES_STORAGE_KEY, JSON.stringify(favorites));
  } catch (e) {
    console.error('保存收藏失败:', e);
  }
};

interface AppState extends UserSession {
  favoriteProductIds: string[];
  setSelfieImage: (image: string | null) => void;
  setSkinAnalysis: (analysis: SkinAnalysis | null) => void;
  setLipRegion: (region: LipRegion | null) => void;
  addProduct: (product: Product) => void;
  removeProduct: (productId: string) => void;
  setProducts: (products: Product[]) => void;
  addTryOnResult: (result: TryOnResult) => void;
  toggleLike: (productId: string) => void;
  toggleFavorite: (productId: string) => void;
  isFavorite: (productId: string) => boolean;
  getFavoriteProducts: () => Product[];
  setRecommendations: (recommendations: Recommendation[]) => void;
  setCurrentStep: (step: number) => void;
  resetSession: () => void;
  availableProducts: Product[];
}

const initialState: UserSession = {
  sessionId: Date.now().toString(),
  selfieImage: null,
  skinAnalysis: null,
  lipRegion: null,
  products: [],
  tryOnResults: [],
  likedProductIds: [],
  recommendations: [],
  currentStep: 0,
};

export const useAppStore = create<AppState>((set, get) => ({
  ...initialState,
  favoriteProductIds: loadFavoritesFromStorage(),
  availableProducts: mockProducts,

  setSelfieImage: (image) => set({ selfieImage: image }),

  setSkinAnalysis: (analysis) => set({ skinAnalysis: analysis }),

  setLipRegion: (region) => set({ lipRegion: region }),

  addProduct: (product) =>
    set((state) => ({
      products: [...state.products, product],
    })),

  removeProduct: (productId) =>
    set((state) => ({
      products: state.products.filter((p) => p.id !== productId),
      tryOnResults: state.tryOnResults.filter((r) => r.productId !== productId),
      likedProductIds: state.likedProductIds.filter((id) => id !== productId),
    })),

  setProducts: (products) => set({ products }),

  addTryOnResult: (result) =>
    set((state) => ({
      tryOnResults: [...state.tryOnResults, result],
    })),

  toggleLike: (productId) =>
    set((state) => {
      const isLiked = state.likedProductIds.includes(productId);
      const newLikedIds = isLiked
        ? state.likedProductIds.filter((id) => id !== productId)
        : [...state.likedProductIds, productId];

      const newTryOnResults = state.tryOnResults.map((r) =>
        r.productId === productId ? { ...r, liked: !isLiked } : r
      );

      return {
        likedProductIds: newLikedIds,
        tryOnResults: newTryOnResults,
      };
    }),

  toggleFavorite: (productId) =>
    set((state) => {
      const isFav = state.favoriteProductIds.includes(productId);
      const newFavorites = isFav
        ? state.favoriteProductIds.filter((id) => id !== productId)
        : [...state.favoriteProductIds, productId];

      saveFavoritesToStorage(newFavorites);

      return {
        favoriteProductIds: newFavorites,
      };
    }),

  isFavorite: (productId) => {
    return get().favoriteProductIds.includes(productId);
  },

  getFavoriteProducts: () => {
    const state = get();
    const allProducts = [...state.availableProducts, ...state.products];
    return allProducts.filter((p) => state.favoriteProductIds.includes(p.id));
  },

  setRecommendations: (recommendations) => set({ recommendations }),

  setCurrentStep: (step) => set({ currentStep: step }),

  resetSession: () =>
    set({
      ...initialState,
      sessionId: Date.now().toString(),
    }),
}));
