import type { SkinAnalysis, RGB } from '@/types';
import { getImageData, loadImage, samplePixels } from './image';
import { rgbToHsl, getWarmCoolScore } from './color';

export const analyzeSkinTone = async (
  imageSrc: string
): Promise<SkinAnalysis> => {
  const img = await loadImage(imageSrc);
  const { imageData, width, height } = getImageData(img, 400);

  const centerX = width / 2;
  const centerY = height / 2;
  const sampleSize = Math.min(width, height) * 0.15;

  const skinPixels = sampleFacePixels(imageData, centerX, centerY, sampleSize);
  const avgColor = averageColor(skinPixels);
  const hsl = rgbToHsl(avgColor.r, avgColor.g, avgColor.b);

  const tone = determineTone(avgColor);
  const depth = determineDepth(hsl.l);
  const undertone = getUndertone(tone, depth);
  const labels = generateLabels(tone, depth, avgColor);

  const dominantColor = `#${avgColor.r.toString(16).padStart(2, '0')}${avgColor.g.toString(16).padStart(2, '0')}${avgColor.b.toString(16).padStart(2, '0')}`;

  return {
    tone,
    depth,
    undertone,
    labels,
    dominantColor,
    brightness: hsl.l,
    redness: (avgColor.r - avgColor.g) / 255,
    yellowness: (avgColor.g - avgColor.b) / 255,
  };
};

const sampleFacePixels = (
  imageData: ImageData,
  centerX: number,
  centerY: number,
  sampleSize: number
): RGB[] => {
  const pixels: RGB[] = [];
  const { width, height, data } = imageData;

  const samplePoints = [
    { x: centerX, y: centerY - sampleSize * 0.3 },
    { x: centerX - sampleSize * 0.4, y: centerY - sampleSize * 0.1 },
    { x: centerX + sampleSize * 0.4, y: centerY - sampleSize * 0.1 },
    { x: centerX - sampleSize * 0.3, y: centerY + sampleSize * 0.2 },
    { x: centerX + sampleSize * 0.3, y: centerY + sampleSize * 0.2 },
    { x: centerX, y: centerY + sampleSize * 0.1 },
  ];

  samplePoints.forEach((point) => {
    for (let i = 0; i < 100; i++) {
      const offsetX = (Math.random() - 0.5) * sampleSize * 0.4;
      const offsetY = (Math.random() - 0.5) * sampleSize * 0.4;
      const x = Math.floor(point.x + offsetX);
      const y = Math.floor(point.y + offsetY);

      if (x >= 0 && x < width && y >= 0 && y < height) {
        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];

        if (isSkinColor(r, g, b)) {
          pixels.push({ r, g, b });
        }
      }
    }
  });

  return pixels.length > 0 ? pixels : samplePixels(imageData, 500);
};

const isSkinColor = (r: number, g: number, b: number): boolean => {
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);

  if (max < 60 || max > 250) return false;
  if (r < g) return false;
  if (r - b < 10) return false;

  const avg = (r + g + b) / 3;
  if (Math.abs(r - avg) < 5 && Math.abs(g - avg) < 5 && Math.abs(b - avg) < 5) {
    return false;
  }

  return true;
};

const averageColor = (pixels: RGB[]): RGB => {
  if (pixels.length === 0) return { r: 200, g: 160, b: 140 };

  const sorted = pixels.sort((a, b) => {
    return a.r + a.g + a.b - (b.r + b.g + b.b);
  });

  const start = Math.floor(sorted.length * 0.25);
  const end = Math.ceil(sorted.length * 0.75);
  const trimmed = sorted.slice(start, end);

  let r = 0,
    g = 0,
    b = 0;
  trimmed.forEach((p) => {
    r += p.r;
    g += p.g;
    b += p.b;
  });

  const count = trimmed.length;
  return {
    r: Math.round(r / count),
    g: Math.round(g / count),
    b: Math.round(b / count),
  };
};

const determineTone = (rgb: RGB): 'warm' | 'cool' | 'neutral' => {
  const hsl = rgbToHsl(rgb.r, rgb.g, rgb.b);
  const score = getWarmCoolScore(hsl.h, hsl.s);

  const rbDiff = rgb.r - rgb.b;
  const gbDiff = rgb.g - rgb.b;

  let warmScore = 0;

  if (rbDiff > 25) warmScore += 1;
  if (gbDiff > 15) warmScore += 1;
  if (score > 0.2) warmScore += 1;
  if (score < -0.2) warmScore -= 1;
  if (rbDiff < 10) warmScore -= 1;

  if (warmScore >= 1) return 'warm';
  if (warmScore <= -1) return 'cool';
  return 'neutral';
};

const determineDepth = (lightness: number): 'fair' | 'light' | 'medium' | 'tan' | 'deep' => {
  if (lightness > 75) return 'fair';
  if (lightness > 60) return 'light';
  if (lightness > 45) return 'medium';
  if (lightness > 30) return 'tan';
  return 'deep';
};

const getUndertone = (
  tone: 'warm' | 'cool' | 'neutral',
  depth: string
): string => {
  const undertones: Record<string, string> = {
    warm: '暖调',
    cool: '冷调',
    neutral: '中性调',
  };
  return undertones[tone];
};

const generateLabels = (
  tone: 'warm' | 'cool' | 'neutral',
  depth: string,
  rgb: RGB
): string[] => {
  const labels: string[] = [];

  const depthLabels: Record<string, string> = {
    fair: '白皙肤色',
    light: '偏白肤色',
    medium: '自然肤色',
    tan: '小麦肤色',
    deep: '健康古铜',
  };

  labels.push(depthLabels[depth] || '自然肤色');
  labels.push(tone === 'warm' ? '暖调肌肤' : tone === 'cool' ? '冷调肌肤' : '中性肌肤');

  const rbRatio = rgb.r / rgb.b;
  if (rbRatio > 1.3) {
    labels.push('偏红肌肤');
  } else if (rbRatio < 1.1) {
    labels.push('偏黄肌肤');
  }

  if (tone === 'warm' && (depth === 'fair' || depth === 'light')) {
    labels.push('适合橘调');
  }
  if (tone === 'cool' && (depth === 'fair' || depth === 'light')) {
    labels.push('适合蓝调红');
  }
  if (tone === 'warm' && (depth === 'medium' || depth === 'tan')) {
    labels.push('适合土橘棕');
  }
  if (tone === 'cool' && (depth === 'medium' || depth === 'tan')) {
    labels.push('适合浆果色');
  }

  return labels.slice(0, 5);
};
