import { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  Sparkles,
  Download,
  Image as ImageIcon,
  Grid3X3,
  Palette,
  Check,
  Loader2,
} from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';
import { generateTryOn } from '@/utils/tryon';
import type { Product } from '@/types';

interface Background {
  id: string;
  name: string;
  gradient: string;
  preview: string;
}

const backgrounds: Background[] = [
  {
    id: 'bg-1',
    name: '玫瑰金',
    gradient: 'linear-gradient(135deg, #B76E79 0%, #E8B4B8 50%, #F5E6E8 100%)',
    preview: 'from-rose-gold-dark via-rose-gold-light to-blush',
  },
  {
    id: 'bg-2',
    name: '经典白',
    gradient: 'linear-gradient(180deg, #FFFFFF 0%, #F8F8F8 100%)',
    preview: 'from-white to-gray-100',
  },
  {
    id: 'bg-3',
    name: '裸粉色',
    gradient: 'linear-gradient(135deg, #F5E6E8 0%, #FDF8F5 100%)',
    preview: 'from-blush to-cream',
  },
  {
    id: 'bg-4',
    name: '金色奢华',
    gradient: 'linear-gradient(135deg, #D4AF37 0%, #F4E5B2 50%, #D4AF37 100%)',
    preview: 'from-gold-dark via-gold-light to-gold',
  },
  {
    id: 'bg-5',
    name: '深酒红',
    gradient: 'linear-gradient(135deg, #4A1F24 0%, #722F37 100%)',
    preview: 'from-wine-dark to-wine',
  },
  {
    id: 'bg-6',
    name: '米白暖调',
    gradient: 'linear-gradient(135deg, #FFF8F0 0%, #F5E6D3 100%)',
    preview: 'from-orange-50 to-orange-100',
  },
  {
    id: 'bg-7',
    name: '冷灰调',
    gradient: 'linear-gradient(135deg, #F5F5F5 0%, #E0E0E0 100%)',
    preview: 'from-gray-100 to-gray-200',
  },
  {
    id: 'bg-8',
    name: '粉紫渐变',
    gradient: 'linear-gradient(135deg, #E8B4B8 0%, #D4A5B5 50%, #C9A0DC 100%)',
    preview: 'from-rose-gold-light via-pink-300 to-purple-300',
  },
];

export default function GalleryPage() {
  const navigate = useNavigate();
  const {
    selfieImage,
    lipRegion,
    availableProducts,
    products,
    favoriteProductIds,
  } = useAppStore();

  const [selectedBackground, setSelectedBackground] = useState<Background>(backgrounds[0]);
  const [selectedProducts, setSelectedProducts] = useState<Product[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [gridImages, setGridImages] = useState<string[]>([]);
  const [generatedCount, setGeneratedCount] = useState(0);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const allProducts = [...availableProducts, ...products];
  const displayProducts = allProducts.length > 0 ? allProducts : availableProducts;

  useEffect(() => {
    if (favoriteProductIds.length > 0) {
      const favProducts = displayProducts.filter((p) =>
        favoriteProductIds.includes(p.id)
      );
      if (favProducts.length >= 3) {
        setSelectedProducts(favProducts.slice(0, 9));
      }
    }
  }, [favoriteProductIds]);

  const toggleProduct = (product: Product) => {
    setSelectedProducts((prev) => {
      if (prev.some((p) => p.id === product.id)) {
        return prev.filter((p) => p.id !== product.id);
      }
      if (prev.length < 9) {
        return [...prev, product];
      }
      return prev;
    });
  };

  const generateGridImage = useCallback(
    async (product: Product, background: Background): Promise<string> => {
      if (!selfieImage) return '';

      try {
        const tryOnImage = lipRegion
          ? await generateTryOn(selfieImage, product.hexColor, lipRegion, 0.75)
          : selfieImage;

        return new Promise((resolve) => {
          const img = new window.Image();
          img.crossOrigin = 'anonymous';
          img.onload = () => {
            const canvas = document.createElement('canvas');
            const size = 400;
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d')!;

            const bgGradient = background.gradient;
            const gradientMatch = bgGradient.match(/linear-gradient\((\d+)deg,\s*([^,]+)\s+(\d+%),\s*([^,]+)\s+(\d+)%/);
            
            if (gradientMatch) {
              const angle = parseInt(gradientMatch[1]);
              const color1 = gradientMatch[2].trim();
              const color2 = gradientMatch[4].trim();
              
              const rad = (angle - 90) * (Math.PI / 180);
              const x1 = size / 2 - Math.cos(rad) * size;
              const y1 = size / 2 - Math.sin(rad) * size;
              const x2 = size / 2 + Math.cos(rad) * size;
              const y2 = size / 2 + Math.sin(rad) * size;
              
              const gradient = ctx.createLinearGradient(x1, y1, x2, y2);
              gradient.addColorStop(0, color1);
              gradient.addColorStop(1, color2);
              ctx.fillStyle = gradient;
            } else {
              ctx.fillStyle = '#FDF8F5';
            }
            ctx.fillRect(0, 0, size, size);

            const scale = Math.min(size / img.width, size / img.height);
            const w = img.width * scale;
            const h = img.height * scale;
            const x = (size - w) / 2;
            const y = (size - h) / 2;
            ctx.drawImage(img, x, y, w, h);

            ctx.fillStyle = 'rgba(255,255,255,0.9)';
            ctx.beginPath();
            ctx.roundRect(10, size - 50, size - 20, 40, 8);
            ctx.fill();
            
            ctx.fillStyle = '#4A1F24';
            ctx.font = 'bold 14px "Noto Sans SC", sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(product.name, size / 2, size - 25);

            ctx.fillStyle = product.hexColor;
            ctx.beginPath();
            ctx.arc(30, size - 30, 12, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.stroke();

            resolve(canvas.toDataURL('image/jpeg', 0.9));
          };
          img.src = tryOnImage;
        });
      } catch (error) {
        console.error('生成图片失败:', error);
        return '';
      }
    },
    [selfieImage, lipRegion]
  );

  const handleGenerate = async () => {
    if (!selfieImage || selectedProducts.length === 0) return;

    setIsGenerating(true);
    setGeneratedCount(0);
    setGridImages([]);

    const images: string[] = [];

    for (let i = 0; i < selectedProducts.length; i++) {
      const img = await generateGridImage(selectedProducts[i], selectedBackground);
      if (img) {
        images.push(img);
        setGridImages([...images]);
        setGeneratedCount(i + 1);
      }
    }

    setIsGenerating(false);
  };

  const handleDownload = () => {
    if (gridImages.length === 0) return;

    const canvas = document.createElement('canvas');
    const cellSize = 400;
    const padding = 20;
    const cols = Math.ceil(Math.sqrt(gridImages.length));
    const rows = Math.ceil(gridImages.length / cols);
    
    canvas.width = cols * cellSize + (cols + 1) * padding;
    canvas.height = rows * cellSize + (rows + 1) * padding;
    const ctx = canvas.getContext('2d')!;

    ctx.fillStyle = '#FDF8F5';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#B76E79';
    ctx.font = 'bold 28px "Playfair Display", serif';
    ctx.textAlign = 'center';
    ctx.fillText('AI 魔镜 - 试色效果对比', canvas.width / 2, padding + 30);

    const loadImages = gridImages.map(
      (src) =>
        new Promise<HTMLImageElement>((resolve) => {
          const img = new window.Image();
          img.onload = () => resolve(img);
          img.src = src;
        })
    );

    Promise.all(loadImages).then((imgs) => {
      imgs.forEach((img, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = padding + col * (cellSize + padding);
        const y = padding + 60 + row * (cellSize + padding);
        ctx.drawImage(img, x, y, cellSize, cellSize);
      });

      const link = document.createElement('a');
      link.download = `AI魔镜-试色对比-${Date.now()}.jpg`;
      link.href = canvas.toDataURL('image/jpeg', 0.95);
      link.click();
    });
  };

  return (
    <div className="container py-12">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-7xl mx-auto"
      >
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => navigate(-1)}
            className="w-10 h-10 rounded-full bg-white/60 flex items-center justify-center text-wine hover:bg-white transition-colors shadow-luxury"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="font-display text-3xl md:text-4xl font-bold text-wine">
              九宫格出图
            </h1>
            <p className="text-wine/60 text-sm mt-1">
              选择背景和口红色号，生成精美对比图
            </p>
          </div>
        </div>

        {!selfieImage ? (
          <div className="card-luxury p-16 text-center">
            <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-blush/50 flex items-center justify-center">
              <ImageIcon className="w-10 h-10 text-rose-gold/50" />
            </div>
            <h3 className="font-semibold text-xl text-wine mb-2">
              请先上传自拍
            </h3>
            <p className="text-wine/60 mb-6">
              九宫格出图需要先上传自拍照片进行试色
            </p>
            <button
              onClick={() => navigate('/selfie')}
              className="btn-rose-gold inline-flex items-center gap-2"
            >
              <Sparkles className="w-5 h-5" />
              前往上传自拍
            </button>
          </div>
        ) : (
          <div className="grid lg:grid-cols-3 gap-8">
            <div className="lg:col-span-1 space-y-6">
              <div className="card-luxury p-6">
                <h3 className="font-semibold text-wine mb-4 flex items-center gap-2">
                  <Palette className="w-5 h-5 text-rose-gold" />
                  选择背景风格
                </h3>
                <div className="grid grid-cols-2 gap-3">
                  {backgrounds.map((bg) => (
                    <button
                      key={bg.id}
                      onClick={() => setSelectedBackground(bg)}
                      className={`relative aspect-video rounded-xl overflow-hidden transition-all ${
                        selectedBackground.id === bg.id
                          ? 'ring-2 ring-gold shadow-gold scale-[1.02]'
                          : 'hover:scale-[1.02]'
                      }`}
                    >
                      <div
                        className="absolute inset-0"
                        style={{ background: bg.gradient }}
                      />
                      <div className="absolute inset-0 flex items-end p-2">
                        <span className="text-xs font-medium bg-black/30 backdrop-blur-sm px-2 py-1 rounded text-white">
                          {bg.name}
                        </span>
                      </div>
                      {selectedBackground.id === bg.id && (
                        <div className="absolute top-2 right-2 w-5 h-5 rounded-full bg-gold flex items-center justify-center">
                          <Check className="w-3 h-3 text-white" />
                        </div>
                      )}
                    </button>
                  ))}
                </div>
              </div>

              <div className="card-luxury p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-semibold text-wine flex items-center gap-2">
                    <Grid3X3 className="w-5 h-5 text-rose-gold" />
                    选择口红色号
                  </h3>
                  <span className="text-sm text-wine/50">
                    已选 {selectedProducts.length}/9
                  </span>
                </div>
                <div className="grid grid-cols-3 gap-2 max-h-[300px] overflow-y-auto pr-2">
                  {displayProducts.map((product) => {
                    const isSelected = selectedProducts.some(
                      (p) => p.id === product.id
                    );
                    return (
                      <button
                        key={product.id}
                        onClick={() => toggleProduct(product)}
                        className={`relative p-2 rounded-lg transition-all ${
                          isSelected
                            ? 'bg-rose-gold-gradient text-white'
                            : 'bg-blush/50 text-wine hover:bg-blush'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          <div
                            className={`w-6 h-6 rounded-full border-2 ${
                              isSelected ? 'border-white' : 'border-white shadow-sm'
                            }`}
                            style={{ backgroundColor: product.hexColor }}
                          />
                          <span className="text-xs truncate">{product.name}</span>
                        </div>
                        {isSelected && (
                          <div className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-white text-rose-gold flex items-center justify-center text-xs font-bold">
                            {selectedProducts.findIndex((p) => p.id === product.id) + 1}
                          </div>
                        )}
                      </button>
                    );
                  })}
                </div>
              </div>

              <button
                onClick={handleGenerate}
                disabled={selectedProducts.length === 0 || isGenerating}
                className="w-full btn-rose-gold flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isGenerating ? (
                  <>
                    <Loader2 className="w-5 h-5 animate-spin" />
                    生成中 {generatedCount}/{selectedProducts.length}
                  </>
                ) : (
                  <>
                    <Sparkles className="w-5 h-5" />
                    生成九宫格
                  </>
                )}
              </button>
            </div>

            <div className="lg:col-span-2">
              <div className="card-luxury p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-semibold text-wine flex items-center gap-2">
                    <Grid3X3 className="w-5 h-5 text-rose-gold" />
                    九宫格预览
                  </h3>
                  {gridImages.length > 0 && (
                    <button
                      onClick={handleDownload}
                      className="flex items-center gap-2 px-4 py-2 rounded-lg bg-gold-gradient text-white font-medium shadow-luxury hover:shadow-gold transition-all"
                    >
                      <Download className="w-4 h-4" />
                      下载图片
                    </button>
                  )}
                </div>

                <div
                  className="bg-gradient-to-br from-blush/30 to-cream rounded-2xl p-4 min-h-[400px] flex items-center justify-center"
                  style={{ background: selectedBackground.gradient }}
                >
                  {gridImages.length === 0 ? (
                    <div className="text-center text-wine/50">
                      <Grid3X3 className="w-16 h-16 mx-auto mb-4 opacity-30" />
                      <p>选择背景和色号后点击生成</p>
                      <p className="text-sm mt-2">最多支持 9 张图片同时对比</p>
                    </div>
                  ) : (
                    <motion.div
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      className="grid gap-2 w-full max-w-2xl"
                      style={{
                        gridTemplateColumns: `repeat(${Math.ceil(Math.sqrt(gridImages.length))}, 1fr)`,
                      }}
                    >
                      {gridImages.map((img, i) => (
                        <motion.div
                          key={i}
                          initial={{ opacity: 0, scale: 0.8 }}
                          animate={{ opacity: 1, scale: 1 }}
                          transition={{ delay: i * 0.1 }}
                          className="aspect-square rounded-lg overflow-hidden shadow-luxury bg-white"
                        >
                          <img
                            src={img}
                            alt={`试色 ${i + 1}`}
                            className="w-full h-full object-cover"
                          />
                        </motion.div>
                      ))}
                    </motion.div>
                  )}
                </div>

                {selectedProducts.length > 0 && gridImages.length === 0 && (
                  <div className="mt-4 flex flex-wrap gap-2">
                    {selectedProducts.map((p, i) => (
                      <div
                        key={p.id}
                        className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-blush/50"
                      >
                        <span className="text-xs text-wine/70">{i + 1}</span>
                        <div
                          className="w-4 h-4 rounded-full border border-white shadow-sm"
                          style={{ backgroundColor: p.hexColor }}
                        />
                        <span className="text-xs text-wine">{p.name}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </motion.div>
    </div>
  );
}