import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  Heart,
  ArrowRight,
  ArrowLeft,
  Sparkles,
  Download,
  ZoomIn,
  SlidersHorizontal,
} from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';
import { generateTryOn } from '@/utils/tryon';
import type { TryOnResult } from '@/types';

export default function TryOnPage() {
  const navigate = useNavigate();
  const {
    selfieImage,
    lipRegion,
    products,
    tryOnResults,
    addTryOnResult,
    toggleLike,
    likedProductIds,
    setCurrentStep,
  } = useAppStore();

  const [isGenerating, setIsGenerating] = useState(true);
  const [generatingIndex, setGeneratingIndex] = useState(0);
  const [selectedProductId, setSelectedProductId] = useState<string | null>(null);
  const [intensity, setIntensity] = useState(75);
  const [showSlider, setShowSlider] = useState(false);

  useEffect(() => {
    const generateAll = async () => {
      if (!selfieImage || !lipRegion || products.length === 0) return;

      setIsGenerating(true);
      setGeneratingIndex(0);

      for (let i = 0; i < products.length; i++) {
        const product = products[i];
        const existing = tryOnResults.find((r) => r.productId === product.id);

        if (!existing) {
          setGeneratingIndex(i);
          try {
            const resultImage = await generateTryOn(
              selfieImage,
              product.hexColor,
              lipRegion,
              intensity / 100
            );

            const result: TryOnResult = {
              id: `tryon-${product.id}`,
              productId: product.id,
              originalImage: selfieImage,
              resultImage,
              lipColor: product.hexColor,
              intensity: intensity / 100,
              liked: false,
              generatedAt: Date.now(),
            };

            addTryOnResult(result);
          } catch (error) {
            console.error('生成试色失败:', error);
          }
        }
      }

      setIsGenerating(false);
      if (products.length > 0 && !selectedProductId) {
        setSelectedProductId(products[0].id);
      }
    };

    generateAll();
  }, [selfieImage, lipRegion, products]);

  const handleIntensityChange = async (value: number) => {
    setIntensity(value);
    if (!selectedProductId || !selfieImage || !lipRegion) return;

    const product = products.find((p) => p.id === selectedProductId);
    if (!product) return;

    try {
      const resultImage = await generateTryOn(
        selfieImage,
        product.hexColor,
        lipRegion,
        value / 100
      );

      const existingIndex = tryOnResults.findIndex(
        (r) => r.productId === selectedProductId
      );
      if (existingIndex >= 0) {
        const updated = [...tryOnResults];
        updated[existingIndex] = {
          ...updated[existingIndex],
          resultImage,
          intensity: value / 100,
        };
      }
    } catch (error) {
      console.error('更新试色失败:', error);
    }
  };

  const selectedResult = tryOnResults.find(
    (r) => r.productId === selectedProductId
  );
  const selectedProduct = products.find((p) => p.id === selectedProductId);

  const handleNext = () => {
    setCurrentStep(4);
    navigate('/recommend');
  };

  const handleBack = () => {
    setCurrentStep(2);
    navigate('/products');
  };

  const handleDownload = () => {
    if (!selectedResult) return;
    const link = document.createElement('a');
    link.download = `试色-${selectedProduct?.name || 'result'}.jpg`;
    link.href = selectedResult.resultImage;
    link.click();
  };

  return (
    <div className="container py-12">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-7xl mx-auto"
      >
        <div className="text-center mb-10">
          <h1 className="font-display text-3xl md:text-4xl font-bold text-wine mb-3">
            试色效果
          </h1>
          <p className="text-wine/60">
            {isGenerating
              ? `正在生成试色效果... (${generatingIndex + 1}/${products.length})`
              : '点击下方缩略图切换，标记喜欢的款式'}
          </p>
        </div>

        <div className="grid lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2">
            <div className="card-luxury p-6">
              <div className="relative aspect-[3/4] rounded-xl overflow-hidden bg-blush/20">
                <AnimatePresence mode="wait">
                  {selectedResult ? (
                    <motion.div
                      key="result"
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      className="relative w-full h-full"
                    >
                      <img
                        src={selectedResult.resultImage}
                        alt="试色效果"
                        className="w-full h-full object-contain"
                      />
                      <div className="absolute top-4 left-4 px-3 py-1.5 rounded-full bg-white/80 backdrop-blur-sm text-sm font-medium text-wine flex items-center gap-2">
                        <div
                          className="w-4 h-4 rounded-full border border-white shadow-sm"
                          style={{ backgroundColor: selectedResult.lipColor }}
                        />
                        {selectedProduct?.name}
                      </div>
                      <button
                        onClick={handleDownload}
                        className="absolute top-4 right-4 w-10 h-10 rounded-full bg-white/80 backdrop-blur-sm flex items-center justify-center text-wine hover:bg-white transition-colors"
                      >
                        <Download className="w-5 h-5" />
                      </button>
                    </motion.div>
                  ) : (
                    <motion.div
                      key="loading"
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      className="absolute inset-0 flex items-center justify-center"
                    >
                      <div className="text-center">
                        <motion.div
                          animate={{
                            scale: [1, 1.1, 1],
                            opacity: [0.5, 1, 0.5],
                          }}
                          transition={{
                            duration: 2,
                            repeat: Infinity,
                            ease: 'easeInOut',
                          }}
                          className="w-20 h-20 mx-auto mb-4 rounded-full bg-rose-gold-gradient flex items-center justify-center"
                        >
                          <Sparkles className="w-10 h-10 text-white" />
                        </motion.div>
                        <p className="text-wine/70 font-medium">
                          AI 正在生成试色效果...
                        </p>
                        <p className="text-wine/50 text-sm mt-1">
                          请稍候，这可能需要几秒钟
                        </p>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>

              <div className="flex items-center justify-between mt-4">
                <button
                  onClick={() => setShowSlider(!showSlider)}
                  className="flex items-center gap-2 px-4 py-2 rounded-lg bg-blush/50 text-wine hover:bg-blush transition-colors"
                >
                  <SlidersHorizontal className="w-4 h-4" />
                  <span className="text-sm font-medium">
                    浓度: {intensity}%
                  </span>
                </button>

                {selectedProduct && (
                  <button
                    onClick={() => toggleLike(selectedProduct.id)}
                    className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all ${
                      likedProductIds.includes(selectedProduct.id)
                        ? 'bg-rose-gold-gradient text-white shadow-luxury'
                        : 'bg-blush/50 text-wine hover:bg-blush'
                    }`}
                  >
                    <Heart
                      className={`w-5 h-5 ${
                        likedProductIds.includes(selectedProduct.id)
                          ? 'fill-current'
                          : ''
                      }`}
                    />
                    <span className="text-sm font-medium">
                      {likedProductIds.includes(selectedProduct.id)
                        ? '已喜欢'
                        : '喜欢'}
                    </span>
                  </button>
                )}
              </div>

              <AnimatePresence>
                {showSlider && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    className="overflow-hidden"
                  >
                    <div className="pt-4 mt-2 border-t border-blush">
                      <input
                        type="range"
                        min="20"
                        max="100"
                        value={intensity}
                        onChange={(e) =>
                          handleIntensityChange(Number(e.target.value))
                        }
                        className="w-full h-2 bg-blush rounded-full appearance-none cursor-pointer accent-rose-gold"
                      />
                      <div className="flex justify-between text-xs text-wine/50 mt-1">
                        <span>淡</span>
                        <span>自然</span>
                        <span>浓</span>
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>

          <div className="space-y-6">
            <div className="card-luxury p-6">
              <h3 className="font-semibold text-wine mb-4 flex items-center gap-2">
                <ZoomIn className="w-5 h-5 text-rose-gold" />
                横向对比
              </h3>
              <div className="space-y-3 max-h-[500px] overflow-y-auto scrollbar-hide pr-2">
                {products.map((product, index) => {
                  const result = tryOnResults.find(
                    (r) => r.productId === product.id
                  );
                  const isSelected = selectedProductId === product.id;
                  const isLiked = likedProductIds.includes(product.id);

                  return (
                    <motion.div
                      key={product.id}
                      initial={{ opacity: 0, x: 20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: index * 0.1 }}
                      onClick={() =>
                        result && setSelectedProductId(product.id)
                      }
                      className={`relative rounded-xl overflow-hidden cursor-pointer transition-all ${
                        isSelected
                          ? 'ring-2 ring-gold shadow-gold scale-[1.02]'
                          : 'hover:shadow-luxury'
                      }`}
                    >
                      <div className="aspect-square bg-blush/30 relative">
                        {result ? (
                          <img
                            src={result.resultImage}
                            alt={product.name}
                            className="w-full h-full object-cover"
                          />
                        ) : (
                          <div className="absolute inset-0 flex items-center justify-center">
                            <div className="w-8 h-8 border-2 border-rose-gold-light/30 border-t-rose-gold rounded-full animate-spin" />
                          </div>
                        )}
                        <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent" />
                        <div className="absolute bottom-0 left-0 right-0 p-3 text-white">
                          <p className="font-medium text-sm">{product.name}</p>
                          <p className="text-xs opacity-80">{product.brand}</p>
                        </div>
                        {isLiked && (
                          <div className="absolute top-2 right-2">
                            <Heart className="w-5 h-5 text-red-500 fill-current drop-shadow" />
                          </div>
                        )}
                      </div>
                    </motion.div>
                  );
                })}
              </div>
            </div>

            <div className="card-luxury p-6">
              <h3 className="font-semibold text-wine mb-3">当前选择</h3>
              {selectedProduct ? (
                <div className="flex items-center gap-4">
                  <div
                    className="w-16 h-16 rounded-full shadow-lg border-4 border-white"
                    style={{ backgroundColor: selectedProduct.hexColor }}
                  />
                  <div>
                    <p className="font-semibold text-wine">
                      {selectedProduct.name}
                    </p>
                    <p className="text-sm text-wine/60">
                      {selectedProduct.category}
                    </p>
                    <p className="text-xs text-wine/40 mt-0.5">
                      {selectedProduct.description}
                    </p>
                  </div>
                </div>
              ) : (
                <p className="text-wine/50 text-sm">请选择一支口红查看详情</p>
              )}
            </div>
          </div>
        </div>

        <div className="flex justify-between mt-10">
          <button
            onClick={handleBack}
            className="btn-outline-gold flex items-center gap-2"
          >
            <ArrowLeft className="w-5 h-5" />
            上一步
          </button>
          <button
            onClick={handleNext}
            disabled={tryOnResults.length === 0 || isGenerating}
            className="btn-rose-gold flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Sparkles className="w-5 h-5" />
            查看智能推荐
            <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      </motion.div>
    </div>
  );
}
