import type { LipRegion } from '@/types';
import { getImageData, loadImage } from './image';
import { rgbToHsl } from './color';

export const detectLipRegion = async (
  imageSrc: string
): Promise<LipRegion> => {
  const img = await loadImage(imageSrc);
  const { imageData, width, height } = getImageData(img, 400);

  const centerX = width / 2;
  const centerY = height * 0.62;

  const lipWidth = width * 0.28;
  const lipHeight = height * 0.12;

  const upperLip = generateUpperLipPoints(centerX, centerY - lipHeight * 0.3, lipWidth, lipHeight * 0.5);
  const lowerLip = generateLowerLipPoints(centerX, centerY + lipHeight * 0.2, lipWidth, lipHeight * 0.7);

  const points = [...upperLip, ...lowerLip.reverse()];

  const boundingBox = {
    x: centerX - lipWidth / 2,
    y: centerY - lipHeight * 0.5,
    width: lipWidth,
    height: lipHeight,
  };

  const refinedPoints = refineLipPoints(imageData, points, boundingBox);

  return {
    points: refinedPoints,
    boundingBox,
    confidence: 0.85,
    upperLip,
    lowerLip,
  };
};

const generateUpperLipPoints = (
  cx: number,
  cy: number,
  width: number,
  height: number
): { x: number; y: number }[] => {
  const points: { x: number; y: number }[] = [];
  const segments = 20;

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const x = cx - width / 2 + width * t;

    const cupidBow = Math.sin(t * Math.PI) * 0.4;
    const leftDip = t < 0.5 ? Math.sin(t * Math.PI * 2) * 0.15 : 0;
    const rightDip = t > 0.5 ? Math.sin((t - 0.5) * Math.PI * 2) * 0.15 : 0;

    const y = cy + height * (cupidBow + leftDip + rightDip - 0.5);
    points.push({ x, y });
  }

  return points;
};

const generateLowerLipPoints = (
  cx: number,
  cy: number,
  width: number,
  height: number
): { x: number; y: number }[] => {
  const points: { x: number; y: number }[] = [];
  const segments = 20;

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const x = cx - width / 2 + width * t;

    const bottomCurve = Math.sin(t * Math.PI) * 0.8;
    const y = cy + height * (bottomCurve - 0.5);
    points.push({ x, y });
  }

  return points;
};

const refineLipPoints = (
  imageData: ImageData,
  initialPoints: { x: number; y: number }[],
  bbox: { x: number; y: number; width: number; height: number }
): { x: number; y: number }[] => {
  const { width, height, data } = imageData;

  return initialPoints.map((point) => {
    let bestX = point.x;
    let bestY = point.y;
    let bestScore = -1;

    const searchRadius = 8;

    for (let dy = -searchRadius; dy <= searchRadius; dy += 2) {
      for (let dx = -searchRadius; dx <= searchRadius; dx += 2) {
        const x = Math.floor(point.x + dx);
        const y = Math.floor(point.y + dy);

        if (x < 0 || x >= width || y < 0 || y >= height) continue;

        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];

        const score = calculateLipScore(r, g, b);

        if (score > bestScore) {
          bestScore = score;
          bestX = x;
          bestY = y;
        }
      }
    }

    return { x: bestX, y: bestY };
  });
};

const calculateLipScore = (r: number, g: number, b: number): number => {
  const hsl = rgbToHsl(r, g, b);

  let hueScore = 0;
  if (hsl.h >= 0 && hsl.h <= 40) {
    hueScore = 1 - Math.abs(hsl.h - 10) / 30;
  } else if (hsl.h >= 340) {
    hueScore = 1 - Math.abs(hsl.h - 355) / 25;
  }

  const satScore = hsl.s > 30 && hsl.s < 80 ? 1 : 0.5;
  const lightScore = hsl.l > 30 && hsl.l < 70 ? 1 : 0.5;

  const rgRatio = r / (g + 1);
  const rbRatio = r / (b + 1);
  const ratioScore = (rgRatio > 1.1 ? 0.5 : 0) + (rbRatio > 1.2 ? 0.5 : 0);

  return hueScore * 0.4 + satScore * 0.2 + lightScore * 0.2 + ratioScore * 0.2;
};

export const isPointInLipRegion = (
  x: number,
  y: number,
  points: { x: number; y: number }[]
): boolean => {
  let inside = false;

  for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
    const xi = points[i].x;
    const yi = points[i].y;
    const xj = points[j].x;
    const yj = points[j].y;

    const intersect =
      yi > y !== yj > y &&
      x < ((xj - xi) * (y - yi)) / (yj - yi) + xi;

    if (intersect) inside = !inside;
  }

  return inside;
};
