import { useState, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  Upload,
  Plus,
  X,
  ArrowRight,
  ArrowLeft,
  Droplet,
  Sparkles,
  Trash2,
  Heart,
} from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';
import { fileToDataUrl, loadImage, resizeImage } from '@/utils/image';
import { extractLipstickColor } from '@/utils/colorExtraction';
import type { Product, ExtractedColor } from '@/types';

export default function ProductsPage() {
  const navigate = useNavigate();
  const {
    products,
    addProduct,
    removeProduct,
    availableProducts,
    setCurrentStep,
    favoriteProductIds,
    toggleFavorite,
  } = useAppStore();

  const [isExtracting, setIsExtracting] = useState(false);
  const [activeTab, setActiveTab] = useState<'upload' | 'preset'>('preset');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFile = useCallback(
    async (file: File) => {
      if (!file.type.startsWith('image/')) return;

      setIsExtracting(true);
      try {
        const dataUrl = await fileToDataUrl(file);
        const img = await loadImage(dataUrl);
        const resized = resizeImage(img, 400, 400);

        const color = await extractLipstickColor(resized);

        const newProduct: Product = {
          id: `custom-${Date.now()}`,
          name: color.name,
          brand: '自定义',
          image: resized,
          hexColor: color.hex,
          extractedColor: color,
          category: color.category,
          description: `上传的${color.category}色号`,
        };

        addProduct(newProduct);
      } catch (error) {
        console.error('颜色提取失败:', error);
      } finally {
        setIsExtracting(false);
      }
    },
    [addProduct]
  );

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    files.forEach((file, index) => {
      setTimeout(() => handleFile(file), index * 300);
    });
  };

  const handleAddPreset = (product: Product) => {
    if (products.some((p) => p.id === product.id)) {
      removeProduct(product.id);
    } else {
      addProduct(product);
    }
  };

  const handleNext = () => {
    if (products.length === 0) return;
    setCurrentStep(3);
    navigate('/tryon');
  };

  const handleBack = () => {
    setCurrentStep(1);
    navigate('/selfie');
  };

  const ColorSwatch = ({ color }: { color: ExtractedColor }) => (
    <div className="flex items-center gap-2">
      <div
        className="w-6 h-6 rounded-full border-2 border-white shadow-md"
        style={{ backgroundColor: color.hex }}
      />
      <div>
        <p className="text-sm font-medium text-wine">{color.name}</p>
        <p className="text-xs text-wine/50">{color.hex.toUpperCase()}</p>
      </div>
    </div>
  );

  return (
    <div className="container py-12">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-6xl mx-auto"
      >
        <div className="text-center mb-10">
          <h1 className="font-display text-3xl md:text-4xl font-bold text-wine mb-3">
            选择你想试的口红
          </h1>
          <p className="text-wine/60">
            上传商品图片或从热门色号中选择，多支一起试更方便对比
          </p>
        </div>

        <div className="flex justify-center mb-8">
          <div className="inline-flex bg-white/60 rounded-full p-1 shadow-luxury">
            <button
              onClick={() => setActiveTab('preset')}
              className={`px-6 py-2 rounded-full font-medium transition-all ${
                activeTab === 'preset'
                  ? 'bg-rose-gold-gradient text-white shadow-md'
                  : 'text-wine/70 hover:text-wine'
              }`}
            >
              热门色号
            </button>
            <button
              onClick={() => setActiveTab('upload')}
              className={`px-6 py-2 rounded-full font-medium transition-all ${
                activeTab === 'upload'
                  ? 'bg-rose-gold-gradient text-white shadow-md'
                  : 'text-wine/70 hover:text-wine'
              }`}
            >
              上传商品图
            </button>
          </div>
        </div>

        <AnimatePresence mode="wait">
          {activeTab === 'preset' ? (
            <motion.div
              key="preset"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4 mb-8"
            >
              {availableProducts.map((product, index) => {
                const isSelected = products.some((p) => p.id === product.id);
                const isFav = favoriteProductIds.includes(product.id);
                return (
                  <motion.div
                    key={product.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.05 }}
                    onClick={() => handleAddPreset(product)}
                    className={`card-luxury p-4 cursor-pointer relative overflow-hidden ${
                      isSelected ? 'ring-2 ring-gold shadow-gold' : ''
                    }`}
                    whileHover={{ y: -4 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleFavorite(product.id);
                      }}
                      className="absolute top-2 left-2 z-10 w-7 h-7 rounded-full bg-white/90 backdrop-blur-sm flex items-center justify-center shadow-md hover:scale-110 transition-transform"
                    >
                      <Heart
                        className={`w-3.5 h-3.5 ${
                          isFav
                            ? 'text-rose-gold fill-current'
                            : 'text-wine/40'
                        }`}
                      />
                    </button>
                    <div className="relative aspect-square rounded-xl overflow-hidden mb-3 bg-blush/30 flex items-center justify-center">
                      <div
                        className="w-3/4 h-3/4 rounded-full shadow-lg"
                        style={{ backgroundColor: product.hexColor }}
                      />
                      <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent" />
                      {isSelected && (
                        <motion.div
                          initial={{ scale: 0 }}
                          animate={{ scale: 1 }}
                          className="absolute top-2 right-2 w-6 h-6 rounded-full bg-gold flex items-center justify-center shadow-md"
                        >
                          <svg
                            className="w-4 h-4 text-white"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={3}
                              d="M5 13l4 4L19 7"
                            />
                          </svg>
                        </motion.div>
                      )}
                    </div>
                    <h4 className="font-medium text-wine text-sm truncate">
                      {product.name}
                    </h4>
                    <p className="text-xs text-wine/50">{product.brand}</p>
                  </motion.div>
                );
              })}
            </motion.div>
          ) : (
            <motion.div
              key="upload"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              className="mb-8"
            >
              <div
                className="card-luxury p-8 border-2 border-dashed border-blush hover:border-rose-gold-light transition-all cursor-pointer"
                onClick={() => fileInputRef.current?.click()}
              >
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  multiple
                  onChange={handleInputChange}
                  className="hidden"
                />
                <div className="text-center">
                  <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-blush/50 flex items-center justify-center">
                    {isExtracting ? (
                      <motion.div
                        animate={{ rotate: 360 }}
                        transition={{
                          duration: 1.5,
                          repeat: Infinity,
                          ease: 'linear',
                        }}
                        className="w-8 h-8 border-4 border-rose-gold-light/30 border-t-rose-gold rounded-full"
                      />
                    ) : (
                      <Plus className="w-8 h-8 text-rose-gold" />
                    )}
                  </div>
                  <h3 className="font-semibold text-wine mb-1">
                    上传口红商品图
                  </h3>
                  <p className="text-sm text-wine/60">
                    支持口红实物图、色卡、商品主图，可同时上传多张
                  </p>
                </div>
              </div>

              {products.filter((p) => p.brand === '自定义').length > 0 && (
                <div className="mt-6">
                  <h3 className="font-semibold text-wine mb-4">已上传的商品</h3>
                  <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                    {products
                      .filter((p) => p.brand === '自定义')
                      .map((product) => (
                        <div
                          key={product.id}
                          className="card-luxury p-4 relative group"
                        >
                          <button
                            onClick={() => removeProduct(product.id)}
                            className="absolute top-2 right-2 w-6 h-6 rounded-full bg-wine/80 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                          {product.image ? (
                            <div className="aspect-square rounded-xl overflow-hidden mb-3">
                              <img
                                src={product.image}
                                alt={product.name}
                                className="w-full h-full object-cover"
                              />
                            </div>
                          ) : (
                            <div
                              className="aspect-square rounded-xl mb-3"
                              style={{ backgroundColor: product.hexColor }}
                            />
                          )}
                          <ColorSwatch color={product.extractedColor} />
                        </div>
                      ))}
                  </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        {products.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="card-luxury p-6 mb-8"
          >
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold text-wine flex items-center gap-2">
                <Droplet className="w-5 h-5 text-rose-gold" />
                已选择 {products.length} 支口红
              </h3>
              <span className="text-sm text-wine/50">
                点击上方色号可添加或移除
              </span>
            </div>
            <div className="flex flex-wrap gap-2">
              {products.map((product) => (
                <motion.div
                  key={product.id}
                  layout
                  initial={{ opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.8 }}
                  className="flex items-center gap-2 px-3 py-2 rounded-full bg-blush/50 border border-blush group"
                >
                  <div
                    className="w-5 h-5 rounded-full border-2 border-white shadow-sm"
                    style={{ backgroundColor: product.hexColor }}
                  />
                  <span className="text-sm font-medium text-wine">
                    {product.name}
                  </span>
                  <button
                    onClick={() => removeProduct(product.id)}
                    className="w-4 h-4 rounded-full bg-wine/20 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <X className="w-3 h-3 text-wine" />
                  </button>
                </motion.div>
              ))}
            </div>
          </motion.div>
        )}

        <div className="flex justify-between">
          <button
            onClick={handleBack}
            className="btn-outline-gold flex items-center gap-2"
          >
            <ArrowLeft className="w-5 h-5" />
            上一步
          </button>
          <button
            onClick={handleNext}
            disabled={products.length === 0}
            className="btn-rose-gold flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Sparkles className="w-5 h-5" />
            生成试色效果
            <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      </motion.div>
    </div>
  );
}
