import type { LipRegion } from '@/types';
import { getImageData, loadImage } from './image';
import { hexToRgb, hslToRgb, rgbToHsl } from './color';
import { isPointInLipRegion } from './lip';

export const generateTryOn = async (
  selfieSrc: string,
  lipColorHex: string,
  lipRegion: LipRegion,
  intensity: number = 0.75
): Promise<string> => {
  const img = await loadImage(selfieSrc);
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d')!;

  canvas.width = img.width;
  canvas.height = img.height;
  ctx.drawImage(img, 0, 0);

  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imageData.data;

  const lipColor = hexToRgb(lipColorHex);
  const lipHsl = rgbToHsl(lipColor.r, lipColor.g, lipColor.b);

  const { boundingBox } = lipRegion;
  const scaledPoints = lipRegion.points.map((p) => ({
    x: p.x * (img.width / (boundingBox.width + boundingBox.x * 2)),
    y: p.y * (img.height / (boundingBox.height + boundingBox.y * 2)),
  }));

  const scaleX = img.width / 400;
  const scaleY = img.height / ((boundingBox.y + boundingBox.height) * 1.6);

  const actualScaleX = scaleX;
  const actualScaleY = scaleX;

  const adjustedPoints = lipRegion.points.map((p) => ({
    x: p.x * actualScaleX + img.width * 0.1,
    y: p.y * actualScaleY + img.height * 0.25,
  }));

  const minX = Math.min(...adjustedPoints.map((p) => p.x));
  const maxX = Math.max(...adjustedPoints.map((p) => p.x));
  const minY = Math.min(...adjustedPoints.map((p) => p.y));
  const maxY = Math.max(...adjustedPoints.map((p) => p.y));

  const centerX = (minX + maxX) / 2;
  const centerY = (minY + maxY) / 2;

  const shiftX = img.width / 2 - centerX;
  const shiftY = img.height * 0.6 - centerY;

  const finalPoints = adjustedPoints.map((p) => ({
    x: p.x + shiftX,
    y: p.y + shiftY,
  }));

  const startX = Math.max(0, Math.floor(Math.min(...finalPoints.map((p) => p.x)) - 10));
  const endX = Math.min(canvas.width, Math.ceil(Math.max(...finalPoints.map((p) => p.x)) + 10));
  const startY = Math.max(0, Math.floor(Math.min(...finalPoints.map((p) => p.y)) - 10));
  const endY = Math.min(canvas.height, Math.ceil(Math.max(...finalPoints.map((p) => p.y)) + 10));

  for (let y = startY; y < endY; y++) {
    for (let x = startX; x < endX; x++) {
      if (!isPointInLipRegion(x, y, finalPoints)) continue;

      const idx = (y * canvas.width + x) * 4;
      const r = data[idx];
      const g = data[idx + 1];
      const b = data[idx + 2];

      const distFromCenter = getDistanceFromLipCenter(x, y, finalPoints);
      const edgeFactor = 1 - Math.min(1, distFromCenter * 1.8);
      const featherFactor = Math.pow(edgeFactor, 0.5);

      const originalHsl = rgbToHsl(r, g, b);

      const mixedH = lipHsl.h;
      const mixedS = Math.min(100, originalHsl.s * 0.3 + lipHsl.s * intensity * 0.7);
      const mixedL = originalHsl.l * 0.5 + lipHsl.l * intensity * 0.5;

      const mixedRgb = hslToRgb(mixedH, mixedS, mixedL);

      const overlayIntensity = intensity * featherFactor;

      const finalR = r * (1 - overlayIntensity * 0.4) + mixedRgb.r * overlayIntensity * 0.6;
      const finalG = g * (1 - overlayIntensity * 0.4) + mixedRgb.g * overlayIntensity * 0.6;
      const finalB = b * (1 - overlayIntensity * 0.4) + mixedRgb.b * overlayIntensity * 0.6;

      const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
      const highlightBoost = luminance > 0.6 ? 1 + (luminance - 0.6) * 0.3 : 1;
      const shadowReduce = luminance < 0.4 ? 1 - (0.4 - luminance) * 0.2 : 1;

      data[idx] = Math.min(255, finalR * highlightBoost * shadowReduce);
      data[idx + 1] = Math.min(255, finalG * highlightBoost * shadowReduce);
      data[idx + 2] = Math.min(255, finalB * highlightBoost * shadowReduce);
    }
  }

  ctx.putImageData(imageData, 0, 0);

  return canvas.toDataURL('image/jpeg', 0.9);
};

const getDistanceFromLipCenter = (
  x: number,
  y: number,
  points: { x: number; y: number }[]
): number => {
  let minDist = Infinity;

  for (let i = 0; i < points.length; i++) {
    const p1 = points[i];
    const p2 = points[(i + 1) % points.length];

    const dist = pointToSegmentDistance(x, y, p1.x, p1.y, p2.x, p2.y);
    minDist = Math.min(minDist, dist);
  }

  const width = Math.max(...points.map((p) => p.x)) - Math.min(...points.map((p) => p.x));
  return Math.min(1, minDist / (width * 0.3));
};

const pointToSegmentDistance = (
  px: number,
  py: number,
  x1: number,
  y1: number,
  x2: number,
  y2: number
): number => {
  const A = px - x1;
  const B = py - y1;
  const C = x2 - x1;
  const D = y2 - y1;

  const dot = A * C + B * D;
  const lenSq = C * C + D * D;
  let param = lenSq !== 0 ? dot / lenSq : -1;

  let xx, yy;

  if (param < 0) {
    xx = x1;
    yy = y1;
  } else if (param > 1) {
    xx = x2;
    yy = y2;
  } else {
    xx = x1 + param * C;
    yy = y1 + param * D;
  }

  const dx = px - xx;
  const dy = py - yy;

  return Math.sqrt(dx * dx + dy * dy);
};

export const generateBeforeAfterComparison = (
  originalSrc: string,
  resultSrc: string
): Promise<string> => {
  return new Promise(async (resolve) => {
    const [originalImg, resultImg] = await Promise.all([
      loadImage(originalSrc),
      loadImage(resultSrc),
    ]);

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d')!;

    const width = originalImg.width * 2 + 20;
    const height = originalImg.height;

    canvas.width = width;
    canvas.height = height;

    ctx.fillStyle = '#FDF8F5';
    ctx.fillRect(0, 0, width, height);

    ctx.drawImage(originalImg, 0, 0);
    ctx.drawImage(resultImg, originalImg.width + 20, 0);

    ctx.fillStyle = 'rgba(255,255,255,0.8)';
    ctx.fillRect(10, 10, 60, 24);
    ctx.fillRect(originalImg.width + 30, 10, 60, 24);

    ctx.fillStyle = '#B76E79';
    ctx.font = '14px "Noto Sans SC", sans-serif';
    ctx.fillText('素颜', 20, 27);
    ctx.fillText('试色后', originalImg.width + 40, 27);

    resolve(canvas.toDataURL('image/jpeg', 0.9));
  });
};
