export const loadImage = (src: string): Promise<HTMLImageElement> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
};

export const getImageData = (
  img: HTMLImageElement,
  maxSize: number = 500
): { imageData: ImageData; width: number; height: number; scale: number } => {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d')!;

  let width = img.width;
  let height = img.height;
  let scale = 1;

  if (width > maxSize || height > maxSize) {
    if (width > height) {
      scale = maxSize / width;
      width = maxSize;
      height = Math.round(img.height * scale);
    } else {
      scale = maxSize / height;
      height = maxSize;
      width = Math.round(img.width * scale);
    }
  }

  canvas.width = width;
  canvas.height = height;
  ctx.drawImage(img, 0, 0, width, height);

  return {
    imageData: ctx.getImageData(0, 0, width, height),
    width,
    height,
    scale,
  };
};

export const getPixelColor = (
  imageData: ImageData,
  x: number,
  y: number
): { r: number; g: number; b: number; a: number } => {
  const idx = (y * imageData.width + x) * 4;
  return {
    r: imageData.data[idx],
    g: imageData.data[idx + 1],
    b: imageData.data[idx + 2],
    a: imageData.data[idx + 3],
  };
};

export const samplePixels = (
  imageData: ImageData,
  sampleCount: number = 1000
): { r: number; g: number; b: number }[] => {
  const pixels: { r: number; g: number; b: number }[] = [];
  const { width, height, data } = imageData;

  for (let i = 0; i < sampleCount; i++) {
    const x = Math.floor(Math.random() * width);
    const y = Math.floor(Math.random() * height);
    const idx = (y * width + x) * 4;

    if (data[idx + 3] > 128) {
      pixels.push({
        r: data[idx],
        g: data[idx + 1],
        b: data[idx + 2],
      });
    }
  }

  return pixels;
};

export const resizeImage = (
  img: HTMLImageElement,
  maxWidth: number,
  maxHeight: number
): string => {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d')!;

  let width = img.width;
  let height = img.height;

  if (width > maxWidth) {
    height = (maxWidth / width) * height;
    width = maxWidth;
  }
  if (height > maxHeight) {
    width = (maxHeight / height) * width;
    height = maxHeight;
  }

  canvas.width = width;
  canvas.height = height;
  ctx.drawImage(img, 0, 0, width, height);

  return canvas.toDataURL('image/jpeg', 0.85);
};

export const fileToDataUrl = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const drawLipRegion = (
  canvas: HTMLCanvasElement,
  points: { x: number; y: number }[],
  color: string = 'rgba(212, 175, 55, 0.8)'
) => {
  const ctx = canvas.getContext('2d')!;
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.setLineDash([5, 5]);

  ctx.beginPath();
  points.forEach((point, i) => {
    if (i === 0) ctx.moveTo(point.x, point.y);
    else ctx.lineTo(point.x, point.y);
  });
  ctx.closePath();
  ctx.stroke();
  ctx.setLineDash([]);
};

export const floodFill = (
  imageData: ImageData,
  startX: number,
  startY: number,
  tolerance: number = 30
): boolean[][] => {
  const { width, height, data } = imageData;
  const mask: boolean[][] = Array(height)
    .fill(null)
    .map(() => Array(width).fill(false));

  const startIdx = (startY * width + startX) * 4;
  const startR = data[startIdx];
  const startG = data[startIdx + 1];
  const startB = data[startIdx + 2];

  const stack: [number, number][] = [[startX, startY]];

  while (stack.length > 0) {
    const [x, y] = stack.pop()!;

    if (x < 0 || x >= width || y < 0 || y >= height || mask[y][x]) continue;

    const idx = (y * width + x) * 4;
    const r = data[idx];
    const g = data[idx + 1];
    const b = data[idx + 2];

    const diff = Math.sqrt(
      Math.pow(r - startR, 2) + Math.pow(g - startG, 2) + Math.pow(b - startB, 2)
    );

    if (diff > tolerance) continue;

    mask[y][x] = true;

    stack.push([x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]);
  }

  return mask;
};
