import type { ExtractedColor, RGB } from '@/types';
import { getImageData, loadImage, samplePixels } from './image';
import {
  rgbToHex,
  rgbToHsl,
  getColorCategory,
  getColorName,
  colorDistance,
} from './color';

export const extractDominantColors = async (
  imageSrc: string,
  count: number = 5
): Promise<ExtractedColor[]> => {
  const img = await loadImage(imageSrc);
  const { imageData } = getImageData(img, 300);

  const pixels = samplePixels(imageData, 2000);
  const filteredPixels = pixels.filter(
    (p) => p.r + p.g + p.b > 100 && p.r + p.g + p.b < 720
  );

  const clusters = kMeans(filteredPixels, count);

  const colors = clusters.map((cluster) => {
    const avg = averageColor(cluster);
    const hsl = rgbToHsl(avg.r, avg.g, avg.b);
    const hex = rgbToHex(avg.r, avg.g, avg.b);

    return {
      hex,
      rgb: avg,
      hsl,
      name: getColorName(hsl.h, hsl.s, hsl.l),
      category: getColorCategory(hsl.h, hsl.s, hsl.l),
      confidence: Math.min(1, cluster.length / 200),
    };
  });

  return colors.sort((a, b) => b.confidence - a.confidence);
};

export const extractLipstickColor = async (
  imageSrc: string
): Promise<ExtractedColor> => {
  const colors = await extractDominantColors(imageSrc, 5);

  const redPinkColors = colors.filter((c) => {
    const h = c.hsl.h;
    return (h < 50 || h > 300) && c.hsl.s > 20;
  });

  const selected = redPinkColors.length > 0 ? redPinkColors[0] : colors[0];

  return selected;
};

const kMeans = (
  pixels: RGB[],
  k: number,
  maxIterations: number = 20
): RGB[][] => {
  if (pixels.length === 0) return Array(k).fill([]);
  if (pixels.length <= k) return pixels.map((p) => [p]);

  let centroids: RGB[] = [];
  const shuffled = [...pixels].sort(() => Math.random() - 0.5);
  for (let i = 0; i < k; i++) {
    centroids.push(shuffled[Math.floor((i / k) * shuffled.length)]);
  }

  for (let iter = 0; iter < maxIterations; iter++) {
    const clusters: RGB[][] = Array(k)
      .fill(null)
      .map(() => []);

    pixels.forEach((pixel) => {
      let minDist = Infinity;
      let minIdx = 0;

      centroids.forEach((centroid, idx) => {
        const dist = colorDistance(pixel, centroid);
        if (dist < minDist) {
          minDist = dist;
          minIdx = idx;
        }
      });

      clusters[minIdx].push(pixel);
    });

    let converged = true;
    const newCentroids: RGB[] = clusters.map((cluster) => {
      const avg = averageColor(cluster);
      const oldCentroid = centroids[clusters.indexOf(cluster)];
      if (colorDistance(avg, oldCentroid) > 2) {
        converged = false;
      }
      return avg;
    });

    centroids = newCentroids;
    if (converged) break;
  }

  const finalClusters: RGB[][] = Array(k)
    .fill(null)
    .map(() => []);

  pixels.forEach((pixel) => {
    let minDist = Infinity;
    let minIdx = 0;

    centroids.forEach((centroid, idx) => {
      const dist = colorDistance(pixel, centroid);
      if (dist < minDist) {
        minDist = dist;
        minIdx = idx;
      }
    });

    finalClusters[minIdx].push(pixel);
  });

  return finalClusters;
};

const averageColor = (pixels: RGB[]): RGB => {
  if (pixels.length === 0) return { r: 128, g: 128, b: 128 };

  let r = 0,
    g = 0,
    b = 0;

  pixels.forEach((p) => {
    r += p.r;
    g += p.g;
    b += p.b;
  });

  return {
    r: Math.round(r / pixels.length),
    g: Math.round(g / pixels.length),
    b: Math.round(b / pixels.length),
  };
};
