import { motion } from 'framer-motion';
import { useNavigate, useLocation } from 'react-router-dom';
import { Sparkles, Heart, Home } from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';

const steps = [
  { id: 0, name: '首页', icon: '✨', path: '/' },
  { id: 1, name: '上传自拍', icon: '📸', path: '/selfie' },
  { id: 2, name: '选择口红', icon: '💄', path: '/products' },
  { id: 3, name: '试色对比', icon: '🎨', path: '/tryon' },
  { id: 4, name: '智能推荐', icon: '🌟', path: '/recommend' },
];

interface LayoutProps {
  children: React.ReactNode;
}

export default function Layout({ children }: LayoutProps) {
  const { currentStep, favoriteProductIds } = useAppStore();
  const navigate = useNavigate();
  const location = useLocation();
  const isFavoritesPage = location.pathname === '/favorites';

  return (
    <div className="min-h-screen flex flex-col">
      <header className="glass-effect sticky top-0 z-50 border-b border-blush/50">
        <div className="container py-4 flex items-center justify-between">
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            onClick={() => navigate('/')}
            className="flex items-center gap-2 cursor-pointer"
          >
            <div className="w-10 h-10 rounded-full bg-rose-gold-gradient flex items-center justify-center shadow-luxury">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <h1 className="font-display text-2xl font-bold text-gradient-rose-gold">
              AI 魔镜
            </h1>
          </motion.div>

          <div className="flex items-center gap-3">
            <motion.button
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ delay: 0.1 }}
              onClick={() => navigate('/')}
              className={`hidden sm:flex items-center gap-2 px-4 py-2 rounded-full transition-all ${
                location.pathname === '/'
                  ? 'bg-rose-gold-gradient text-white shadow-luxury'
                  : 'bg-white/60 text-wine/70 hover:bg-blush/50'
              }`}
            >
              <Home className="w-4 h-4" />
              <span className="text-sm font-medium">首页</span>
            </motion.button>

            <motion.button
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ delay: 0.2 }}
              onClick={() => navigate('/favorites')}
              className={`relative flex items-center gap-2 px-4 py-2 rounded-full transition-all ${
                isFavoritesPage
                  ? 'bg-rose-gold-gradient text-white shadow-luxury'
                  : 'bg-white/60 text-wine/70 hover:bg-blush/50'
              }`}
            >
              <Heart
                className={`w-4 h-4 ${isFavoritesPage ? 'fill-current' : ''}`}
              />
              <span className="text-sm font-medium">收藏</span>
              {favoriteProductIds.length > 0 && (
                <motion.span
                  key={favoriteProductIds.length}
                  initial={{ scale: 0.5, opacity: 0 }}
                  animate={{ scale: 1, opacity: 1 }}
                  className={`absolute -top-1 -right-1 w-5 h-5 rounded-full text-xs font-bold flex items-center justify-center ${
                    isFavoritesPage
                      ? 'bg-white text-rose-gold'
                      : 'bg-rose-gold-gradient text-white'
                  }`}
                >
                  {favoriteProductIds.length}
                </motion.span>
              )}
            </motion.button>
          </div>
        </div>

        {currentStep > 0 && (
          <div className="border-t border-blush/30">
            <div className="container py-2.5 hidden md:flex items-center justify-center gap-2">
              {steps.slice(1).map((step, index) => (
                <div key={step.id} className="flex items-center">
                  <motion.div
                    initial={{ scale: 0.8, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    transition={{ delay: index * 0.1 }}
                    onClick={() => navigate(step.path)}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-full transition-all cursor-pointer ${
                      currentStep >= step.id
                        ? 'bg-rose-gold-gradient text-white shadow-luxury'
                        : 'bg-blush/50 text-wine/60 hover:bg-blush/70'
                    }`}
                  >
                    <span className="text-sm">{step.icon}</span>
                    <span className="text-sm font-medium">{step.name}</span>
                  </motion.div>
                  {index < steps.length - 2 && (
                    <div
                      className={`w-6 h-0.5 mx-1 ${
                        currentStep > step.id ? 'bg-gold' : 'bg-blush'
                      }`}
                    />
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </header>

      <main className="flex-1">{children}</main>

      <footer className="border-t border-blush/50 py-6 mt-12">
        <div className="container text-center text-wine/50 text-sm">
          <p>AI 魔镜 - 智能试色与个性化推荐</p>
          <p className="mt-1">让每一支口红都遇见对的人 ✨</p>
        </div>
      </footer>
    </div>
  );
}
