import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  Heart,
  Trash2,
  ArrowLeft,
  Sparkles,
  BookmarkX,
  Palette,
  Play,
} from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';
import type { Product } from '@/types';

export default function FavoritesPage() {
  const navigate = useNavigate();
  const { getFavoriteProducts, toggleFavorite, favoriteProductIds, addProduct } =
    useAppStore();

  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const favorites = getFavoriteProducts();

  const categories = ['全部', ...new Set(favorites.map((p) => p.category))];

  const filteredFavorites =
    selectedCategory === '全部'
      ? favorites
      : favorites.filter((p) => p.category === selectedCategory);

  const handleTryOn = (product: Product) => {
    const existing = useAppStore.getState().products.find((p) => p.id === product.id);
    if (!existing) {
      addProduct(product);
    }
    navigate('/selfie');
  };

  return (
    <div className="container py-12">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-6xl mx-auto"
      >
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate(-1)}
              className="w-10 h-10 rounded-full bg-white/60 flex items-center justify-center text-wine hover:bg-white transition-colors shadow-luxury"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div>
              <h1 className="font-display text-3xl md:text-4xl font-bold text-wine">
                我的收藏
              </h1>
              <p className="text-wine/60 text-sm mt-1">
                已收藏 {favorites.length} 支色号
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-gradient-to-r from-rose-gold-light/20 to-gold/20 border border-gold/30">
            <Heart className="w-5 h-5 text-rose-gold fill-current" />
            <span className="font-semibold text-wine">
              {favorites.length}
            </span>
          </div>
        </div>

        {favorites.length > 0 && (
          <div className="flex flex-wrap gap-2 mb-8">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-all ${
                  selectedCategory === cat
                    ? 'bg-rose-gold-gradient text-white shadow-luxury'
                    : 'bg-white/60 text-wine/70 hover:bg-blush/50'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        )}

        <AnimatePresence mode="wait">
          {favorites.length === 0 ? (
            <motion.div
              key="empty"
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              className="card-luxury p-16 text-center"
            >
              <div className="w-24 h-24 mx-auto mb-6 rounded-full bg-blush/50 flex items-center justify-center">
                <BookmarkX className="w-12 h-12 text-rose-gold/50" />
              </div>
              <h3 className="font-semibold text-xl text-wine mb-2">
                还没有收藏的色号
              </h3>
              <p className="text-wine/60 mb-6">
                浏览热门色号，把喜欢的口红加入收藏吧
              </p>
              <button
                onClick={() => navigate('/products')}
                className="btn-rose-gold inline-flex items-center gap-2"
              >
                <Palette className="w-5 h-5" />
                去逛逛
              </button>
            </motion.div>
          ) : (
            <motion.div
              key="list"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-5"
            >
              {filteredFavorites.map((product, index) => (
                <motion.div
                  key={product.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.9 }}
                  transition={{ delay: index * 0.05 }}
                  layout
                  className="card-luxury p-5 group relative overflow-hidden"
                >
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      toggleFavorite(product.id);
                    }}
                    className="absolute top-3 right-3 z-10 w-8 h-8 rounded-full bg-white/90 backdrop-blur-sm flex items-center justify-center shadow-md hover:scale-110 transition-transform"
                  >
                    <Heart className="w-4 h-4 text-rose-gold fill-current" />
                  </button>

                  <div className="relative aspect-square rounded-xl overflow-hidden mb-4 bg-blush/30 flex items-center justify-center group-hover:scale-105 transition-transform duration-300">
                    <div
                      className="w-3/4 h-3/4 rounded-full shadow-lg"
                      style={{ backgroundColor: product.hexColor }}
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                  </div>

                  <div className="space-y-1">
                    <h4 className="font-semibold text-wine truncate">
                      {product.name}
                    </h4>
                    <p className="text-xs text-wine/50">{product.brand}</p>
                    <div className="flex items-center gap-2 pt-1">
                      <div
                        className="w-4 h-4 rounded-full border border-white shadow-sm flex-shrink-0"
                        style={{ backgroundColor: product.hexColor }}
                      />
                      <span className="text-xs text-wine/60 truncate">
                        {product.category}
                      </span>
                    </div>
                  </div>

                  <button
                    onClick={() => handleTryOn(product)}
                    className="mt-4 w-full py-2 rounded-lg bg-blush/50 text-wine text-sm font-medium hover:bg-rose-gold hover:text-white transition-all flex items-center justify-center gap-1.5 group-hover:bg-rose-gold-gradient group-hover:text-white"
                  >
                    <Play className="w-4 h-4" />
                    立即试色
                  </button>
                </motion.div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>

        {favorites.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="mt-10 card-luxury p-6 bg-gradient-to-r from-rose-gold-light/5 to-gold/5"
          >
            <div className="flex items-center justify-between flex-wrap gap-4">
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 rounded-full bg-rose-gold-gradient flex items-center justify-center">
                  <Sparkles className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h3 className="font-semibold text-wine">
                    一键试色所有收藏
                  </h3>
                  <p className="text-sm text-wine/60">
                    快速体验收藏夹中所有色号的上唇效果
                  </p>
                </div>
              </div>
              <button
                onClick={() => {
                  favorites.forEach((p) => {
                    const existing = useAppStore
                      .getState()
                      .products.find((prod) => prod.id === p.id);
                    if (!existing) {
                      useAppStore.getState().addProduct(p);
                    }
                  });
                  navigate('/selfie');
                }}
                className="btn-rose-gold flex items-center gap-2"
              >
                <Sparkles className="w-5 h-5" />
                全部试色
              </button>
            </div>
          </motion.div>
        )}
      </motion.div>
    </div>
  );
}
