import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  Crown,
  Sparkles,
  ArrowLeft,
  RotateCcw,
  Heart,
  Quote,
  Palette,
  Sun,
  Snowflake,
} from 'lucide-react';
import { useAppStore } from '@/store/useAppStore';
import { generateRecommendations, analyzeUserPreferences } from '@/utils/recommend';
import type { Recommendation } from '@/types';

export default function RecommendPage() {
  const navigate = useNavigate();
  const {
    products,
    skinAnalysis,
    likedProductIds,
    setRecommendations,
    recommendations,
    setCurrentStep,
    resetSession,
  } = useAppStore();

  const [sortedRecs, setSortedRecs] = useState<Recommendation[]>([]);
  const [sortBy, setSortBy] = useState<'match' | 'skin' | 'preference'>('match');

  useEffect(() => {
    if (products.length > 0 && skinAnalysis) {
      const recs = generateRecommendations(
        products,
        skinAnalysis,
        likedProductIds
      );
      setRecommendations(recs);
      setSortedRecs(recs);
    }
  }, [products, skinAnalysis, likedProductIds]);

  useEffect(() => {
    if (recommendations.length > 0) {
      let sorted = [...recommendations];
      if (sortBy === 'match') {
        sorted.sort((a, b) => b.matchScore - a.matchScore);
      } else if (sortBy === 'skin') {
        sorted.sort((a, b) => b.skinMatch - a.skinMatch);
      } else {
        sorted.sort((a, b) => b.preferenceMatch - a.preferenceMatch);
      }
      setSortedRecs(sorted);
    }
  }, [sortBy, recommendations]);

  const preferences = analyzeUserPreferences(products, likedProductIds);

  const getProduct = (productId: string) =>
    products.find((p) => p.id === productId);

  const handleRestart = () => {
    resetSession();
    navigate('/');
  };

  const handleBack = () => {
    setCurrentStep(3);
    navigate('/tryon');
  };

  const depthLabels: Record<string, string> = {
    fair: '白皙',
    light: '偏白',
    medium: '自然',
    tan: '小麦',
    deep: '健康古铜',
  };

  const CircularProgress = ({
    value,
    size = 60,
    strokeWidth = 5,
    color = '#B76E79',
  }: {
    value: number;
    size?: number;
    strokeWidth?: number;
    color?: string;
  }) => {
    const radius = (size - strokeWidth) / 2;
    const circumference = radius * 2 * Math.PI;
    const offset = circumference - (value / 100) * circumference;

    return (
      <div className="relative" style={{ width: size, height: size }}>
        <svg width={size} height={size} className="transform -rotate-90">
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke="#F5E6E8"
            strokeWidth={strokeWidth}
          />
          <motion.circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke={color}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeDasharray={circumference}
            initial={{ strokeDashoffset: circumference }}
            animate={{ strokeDashoffset: offset }}
            transition={{ duration: 1, ease: 'easeOut' }}
          />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-sm font-bold" style={{ color }}>
            {value}%
          </span>
        </div>
      </div>
    );
  };

  return (
    <div className="container py-12">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-6xl mx-auto"
      >
        <div className="text-center mb-10">
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: 'spring', delay: 0.2 }}
            className="inline-flex items-center gap-2 px-5 py-2 rounded-full bg-gradient-to-r from-gold/20 to-rose-gold-light/20 border border-gold/30 mb-6"
          >
            <Sparkles className="w-5 h-5 text-gold" />
            <span className="font-medium text-wine">AI 智能推荐</span>
          </motion.div>
          <h1 className="font-display text-3xl md:text-4xl font-bold text-wine mb-3">
            为你精选的本命口红
          </h1>
          <p className="text-wine/60">
            基于你的肤色特征和审美偏好，AI 为你精准推荐
          </p>
        </div>

        {skinAnalysis && (
          <div className="grid md:grid-cols-3 gap-6 mb-10">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="card-luxury p-6"
            >
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 rounded-full bg-rose-gold-gradient flex items-center justify-center">
                  <Palette className="w-5 h-5 text-white" />
                </div>
                <h3 className="font-semibold text-wine">你的肤色</h3>
              </div>
              <div className="flex items-center gap-4">
                <div
                  className="w-16 h-16 rounded-full shadow-lg border-4 border-white"
                  style={{ backgroundColor: skinAnalysis.dominantColor }}
                />
                <div>
                  <p className="font-semibold text-wine">
                    {depthLabels[skinAnalysis.depth]}
                  </p>
                  <p className="text-rose-gold text-sm font-medium">
                    {skinAnalysis.tone === 'warm' ? '暖调' : skinAnalysis.tone === 'cool' ? '冷调' : '中性调'}
                  </p>
                </div>
              </div>
            </motion.div>

            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
              className="card-luxury p-6"
            >
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 rounded-full bg-gold-gradient flex items-center justify-center">
                  {skinAnalysis.tone === 'warm' ? (
                    <Sun className="w-5 h-5 text-white" />
                  ) : (
                    <Snowflake className="w-5 h-5 text-white" />
                  )}
                </div>
                <h3 className="font-semibold text-wine">冷暖调分析</h3>
              </div>
              <div className="flex items-center justify-around">
                <div className="text-center">
                  <div className="text-2xl mb-1">☀️</div>
                  <p className="text-xs text-wine/60">暖调</p>
                </div>
                <div className="flex-1 h-2 mx-3 bg-gradient-to-r from-orange-300 via-pink-300 to-blue-300 rounded-full relative">
                  <motion.div
                    initial={{ left: '50%' }}
                    animate={{
                      left:
                        skinAnalysis.tone === 'warm'
                          ? '20%'
                          : skinAnalysis.tone === 'cool'
                          ? '80%'
                          : '50%',
                    }}
                    transition={{ duration: 1, delay: 0.5 }}
                    className="absolute top-1/2 -translate-y-1/2 w-4 h-4 bg-white rounded-full shadow-md border-2 border-rose-gold"
                  />
                </div>
                <div className="text-center">
                  <div className="text-2xl mb-1">❄️</div>
                  <p className="text-xs text-wine/60">冷调</p>
                </div>
              </div>
            </motion.div>

            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 }}
              className="card-luxury p-6"
            >
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 rounded-full bg-wine flex items-center justify-center">
                  <Heart className="w-5 h-5 text-white" />
                </div>
                <h3 className="font-semibold text-wine">你的偏好</h3>
              </div>
              {likedProductIds.length > 0 ? (
                <div>
                  <div className="flex flex-wrap gap-1.5 mb-2">
                    {preferences.styleTags.map((tag, i) => (
                      <motion.span
                        key={tag}
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        transition={{ delay: 0.5 + i * 0.1 }}
                        className="px-2.5 py-1 rounded-full bg-blush/70 text-wine text-xs"
                      >
                        {tag}
                      </motion.span>
                    ))}
                  </div>
                  <p className="text-xs text-wine/50">
                    喜欢 {likedProductIds.length} 支 ·{' '}
                    {preferences.preferredCategories.slice(0, 2).join('、')}
                  </p>
                </div>
              ) : (
                <p className="text-sm text-wine/50">
                  在试色页标记喜欢的款式，获得更精准的推荐
                </p>
              )}
            </motion.div>
          </div>
        )}

        <div className="flex items-center justify-between mb-6">
          <h2 className="font-semibold text-xl text-wine">推荐榜单</h2>
          <div className="flex gap-2">
            {[
              { key: 'match', label: '综合匹配' },
              { key: 'skin', label: '肤色匹配' },
              { key: 'preference', label: '偏好匹配' },
            ].map((option) => (
              <button
                key={option.key}
                onClick={() => setSortBy(option.key as typeof sortBy)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${
                  sortBy === option.key
                    ? 'bg-rose-gold-gradient text-white shadow-md'
                    : 'bg-white/60 text-wine/70 hover:bg-blush/50'
                }`}
              >
                {option.label}
              </button>
            ))}
          </div>
        </div>

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6 mb-10">
          <AnimatePresence>
            {sortedRecs.map((rec, index) => {
              const product = getProduct(rec.productId);
              if (!product) return null;

              const isTop1 = rec.rank === 1;

              return (
                <motion.div
                  key={rec.productId}
                  initial={{ opacity: 0, y: 30 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  transition={{ delay: index * 0.1 }}
                  layout
                  className={`card-luxury p-6 relative overflow-hidden ${
                    isTop1 ? 'ring-2 ring-gold shadow-gold' : ''
                  }`}
                >
                  {isTop1 && (
                    <motion.div
                      initial={{ scale: 0, rotate: -20 }}
                      animate={{ scale: 1, rotate: 0 }}
                      transition={{
                        type: 'spring',
                        delay: index * 0.1 + 0.3,
                      }}
                      className="absolute -top-1 -right-1 w-14 h-14 bg-gradient-to-br from-gold to-gold-light flex items-center justify-center shadow-lg"
                      style={{
                        clipPath:
                          'polygon(0 0, 100% 0, 100% 100%, 0 0)',
                      }}
                    >
                      <Crown className="w-5 h-5 text-white absolute top-2 right-2" />
                    </motion.div>
                  )}

                  <div className="flex items-start gap-4 mb-4">
                    <div
                      className="w-20 h-20 rounded-2xl shadow-lg flex-shrink-0 relative overflow-hidden"
                      style={{ backgroundColor: product.hexColor }}
                    >
                      <div className="absolute inset-0 bg-gradient-to-br from-white/30 to-transparent" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h3 className="font-semibold text-lg text-wine truncate">
                        {product.name}
                      </h3>
                      <p className="text-sm text-wine/60 mb-2">
                        {product.brand} · {product.category}
                      </p>
                      <div className="flex items-center gap-3">
                        <div className="flex flex-col items-center">
                          <CircularProgress
                            value={rec.matchScore}
                            size={44}
                            strokeWidth={4}
                          />
                          <span className="text-[10px] text-wine/50 mt-1">
                            综合
                          </span>
                        </div>
                        <div className="flex flex-col items-center">
                          <CircularProgress
                            value={rec.skinMatch}
                            size={44}
                            strokeWidth={4}
                            color="#D4AF37"
                          />
                          <span className="text-[10px] text-wine/50 mt-1">
                            肤色
                          </span>
                        </div>
                        <div className="flex flex-col items-center">
                          <CircularProgress
                            value={rec.preferenceMatch}
                            size={44}
                            strokeWidth={4}
                            color="#E8B4B8"
                          />
                          <span className="text-[10px] text-wine/50 mt-1">
                            偏好
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    {rec.reasons.map((reason, i) => (
                      <motion.div
                        key={i}
                        initial={{ opacity: 0, x: -10 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: index * 0.1 + i * 0.1 + 0.3 }}
                        className="flex gap-2 text-sm"
                      >
                        <Quote className="w-4 h-4 text-gold flex-shrink-0 mt-0.5" />
                        <p className="text-wine/70 leading-relaxed">{reason}</p>
                      </motion.div>
                    ))}
                  </div>

                  {isTop1 && (
                    <motion.div
                      initial={{ opacity: 0, y: 10 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: index * 0.1 + 0.5 }}
                      className="mt-4 pt-4 border-t border-blush"
                    >
                      <div className="flex items-center justify-center gap-2 text-gold">
                        <Crown className="w-4 h-4" />
                        <span className="font-semibold text-sm">
                          TOP 1 推荐
                        </span>
                      </div>
                    </motion.div>
                  )}
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>

        <div className="flex justify-between items-center">
          <button
            onClick={handleBack}
            className="btn-outline-gold flex items-center gap-2"
          >
            <ArrowLeft className="w-5 h-5" />
            返回试色
          </button>
          <button
            onClick={handleRestart}
            className="btn-rose-gold flex items-center gap-2"
          >
            <RotateCcw className="w-5 h-5" />
            重新开始
          </button>
        </div>
      </motion.div>
    </div>
  );
}
